quests[44761] = { id = 44761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Runebound Scroll" }
quests[44764] = { id = 44764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getarnter Dämon", description = "Während Ihr bei diesem Dämon Euren... Einfluss geltend gemacht habt, habe ich es geschafft, die verderbten Essenzen zu einer einfacheren, praktischeren Form zu destillieren.\n\nIch habe Khadgar gebeten, Euch das Resultat zu übergeben, nachdem er einen Blick darauf geworfen hat, aber ich muss Euch eindringlich daran erinnern, dass diese Essenzen recht stark sind, sogar gefährlich, wenn man sie nicht mit höchster Vorsicht behandelt.\n\nSprecht mit Khadgar, wenn Ihr bereit seid, anzufangen.", sourceObjective = "Sprecht mit Erzmagier Khadgar am Gebirgspass der Totenwinde.", completion = "Die Proben haben sich als sehr nützlich erwiesen. Ebenso wie Eure... Einflussnahme.", sourceObjectiveStatus = "unverified-source-field" }
quests[44765] = { id = 44765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anglerwettbewerb im Schlingendorntal", progress = "Hat etwas angebissen?", completion = "Beeilt Euch und reicht den Fisch rüber, wenn Ihr gewinnen wollt!" }
quests[44766] = { id = 44766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plan B", description = "Dalaran scheint auf den ersten Blick nur eine schwebende Stadt zu sein, dabei ist sie in Wahrheit eine mächtige magische Waffe. Es wird etwas dauern, die arkanen Verteidigungssysteme zu reparieren, und die Legion wird dies ausnutzen wollen.\n\nWir brauchen unbedingt einen Plan B, und zwar sofort! \n\nErzmagier Kalec kennt sich mit solchen Dingen gut aus. Vielleicht könnt Ihr mit ihm sprechen?", sourceObjective = "Sprecht mit Erzmagier Kalec.", completion = "Hm. Eine interessante Herausforderung!", sourceObjectiveStatus = "unverified-source-field" }
quests[44767] = { id = 44767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine himmlische Einladung", description = "Seid gegrüßt, <Sterblicher/Sterbliche>.\n\nSchon seit vielen Jahren beobachte ich diesen Planeten. Mit Ausnahme von gelegentlichem Flüstern aus der Dunkelheit ist es in den Hallen von Ulduar still und leer. Es langweilt mich so sehr!\n\nDeshalb habe auch ich mit diesen \"Haustierkämpfen\" begonnen, die Euch so viel zu bedeuten scheinen. Es ist schon ein amüsanter Zeitvertreib, der meinen Verstand viele Jahrhunderte lang beschäftigen wird!\n\nIch durchsuche die Sterne nach klitzekleinen Wesen voll kosmischer Macht, um meine Sammlung zu erweitern. Kommt, lasst uns erneut kämpfen!", sourceObjective = "Besiegt Algalon den Beobachter in einem Haustierkampf.", completion = "Ah, wie ein frischer Sonnenwind. Nehmt diese, meine liebste Konstellation, möge sie Euch an die Hüter erinnern, die über uns alle wachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44768] = { id = 44768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nyells Werkstatt", description = "Soweit ich es verstanden habe, ist dies die Werkstatt von Meisterkonstrukteur Nyell. Seine Fähigkeiten in der Konstruktherstellung sind unübertroffen!\n\nWas für eine Schande, dass er der Legion die Treue geschworen hat. Ich hasse es, einen so erfahrenen Konstrukteur ausschalten zu müssen, aber wir haben keine Wahl.\n\nWenn Ihr Glück habt, liegt hier sogar noch irgendwo ein alter Schildgenerator herum.", sourceObjective = "Tötet Meisterkonstrukteur Nyell.", progress = "Hattet Ihr Erfolg?", completion = "Ein Unterstützer der Legion weniger, um den wir uns Sorgen machen müssen. Oh, und einen Schildgenerator habt Ihr auch gefunden? Wunderbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[44769] = { id = 44769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewaffnung der Bevölkerung" }
quests[44770] = { id = 44770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Shal'dorei", description = "Diese Werkstatt enthält eine umfangreiche Sammlung seltener Schriftrollen, die von meinem Volk geschrieben wurden. Wir alle profitieren davon, wenn wir Informationen teilen, oder seid Ihr anderer Meinung?\n\nVielleicht wird die Tirisgarde mich und meinesgleichen etwas freundlicher aufnehmen, wenn wir einen solchen Schatz mitbringen...\n\nBitte nehmt so viel, wie Ihr könnt.", sourceObjective = "Sammelt 8 uralte Schriftrollen der Shal'dorei.", progress = "Habt Ihr ein paar Schriftrollen gefunden?", completion = "Nur wenige der von den alten Shal'dorei geschriebenen Texte sind geblieben. Ich bin sicher, die Bibliothekare der Tirisgarde werden von diesen hier entzückt sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[44771] = { id = 44771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bedrohung naht", description = "Es ist an der Zeit, dass ich Euch eine weitere Geschichte erzähle. Könntet Ihr mir einen Grog holen, während Ihr zuhört? Ich habe einen fürchterlichen Durst.\n\nDas Fass ist sehr alt und der Hahn lässt den Grog nur sehr langsam heraus.", sourceObjective = "Schenkt Havi etwas Grog ein.", progress = "Ich habe Euch die Geschichte erzählt, aber habt Ihr mir den Grog gebracht?", completion = "Der ist köstlich. Ich danke Euch.\n\nBevor wir handeln, müssen wir mehr über Helyas Pläne in Erfahrung bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44772] = { id = 44772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ch 5 Available Tracking Quest" }
quests[44775] = { id = 44775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel der Knochen", description = "Während Ihr fort wart, haben wir eine Strategie entworfen, wie wir das Geschirr nutzen können. Mit seiner Hilfe können wir die Geister der verstorbenen Drachen an Euch binden und sie damit zu Euch treu ergebenen Soldaten machen.\n\nIch habe Minerva zum Thorimshorn in Sturmheim geschickt, wo sie eine Brut gefallener Thorignir gefunden hat. Sie sind unsere primären Ziele.\n\nBittet Grimmschwinge, Euch zum Berg zu fliegen. Minerva wird Euch dort die Details erklären.", sourceObjective = "Bittet Grimmschwinge, Euch zum Thorimshorn zu fliegen, damit Ihr dort Minerva treffen könnt.", completion = "Da seid Ihr ja endlich, Todesgebieter. Ich musste so lange warten, dass ich fast schon wieder gestorben wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[44777] = { id = 44777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NEU VERWENDEN" }
quests[44780] = { id = 44780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revanche" }
quests[44781] = { id = 44781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Council's Call" }
quests[44782] = { id = 44782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht für die Öffentlichkeit", description = "Kriege werden nicht allein von Armeen gewonnen, die tapfer über das Schlachtfeld stürmen, {class}t.\n\nManchmal sind die Taten die wichtigsten, die Einzelne in Kämpfen vollbringen, von denen nur wenige jemals erfahren. Aus diesem Grund... \n\n<Khadgar runzelt leicht die Stirn.>\n\nWir sollten das lieber an einem etwas privateren Ort besprechen. Lasst uns hinauf in den Purpursalon gehen, ja?", sourceObjective = "Sucht den Rat der Sechs im Purpursalon oberhalb der Violetten Zitadelle auf.", completion = "Keine Sorge, sie wird sich wieder erholen.\n\nWelcher Dämon ihr das auch immer angetan hat, er war nicht lang genug vor Ort, um seine Tat zu Ende zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44783] = { id = 44783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auferstanden aus Knochen", description = "So, die Aufgabe lautet, die Brutmutter unter unsere Kontrolle zu bringen. Aber hört zu: Ein paar mehr Drachen wären doch auch ein Segen, oder?\n\nWenn wir schon mal hier sind, könnten wir doch unsere fabelhaften Kräfte über die Untoten dafür verwenden, ein paar von ihnen wiederauferstehen zu lassen, nicht wahr? Der Gipfel hat ihre Körper zwar in Eis gebettet, aber die... warme... Umarmung des Untodes wäre ihnen bestimmt viel lieber. Wir müssen ihre gefrorenen Leichen finden und ihnen unseren Willen einhauchen.", sourceObjective = "Lasst 4 verstorbene Thorignir am Thorimshorn wiederauferstehen.", completion = "Ich konnte ihre Energie spüren, selbst im Untod.", sourceObjectiveStatus = "unverified-source-field" }
quests[44784] = { id = 44784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgeschrittene Zauberstabkunde" }
quests[44785] = { id = 44785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teekränzchen", description = "Ich... E-Es tut mir leid. Ich... Ich kann nicht...\n\n\n<Ihr hört Fußschritte hinter Euch.>\n\n\nA... Anneke? Was...", sourceObjective = "Findet Anneke Lehmann.", completion = "War das wirklich Anneke? Hat sie dieses... Ding hervorgebracht? Vor nicht allzu langer Zeit hielten wir sie noch für tot.\n\nWas haben wir nur getan, um ein solches... ein solches Grauen über unser Dorf hereinbrechen zu lassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44786] = { id = 44786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwischenprüfung: Runenfähigkeit" }
quests[44787] = { id = 44787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochenmutter", description = "Es ist an der Zeit, dass wir uns um die Brutmutter kümmern, den wahren Grund, warum wir hier sind. Sie ist sehr stark und diese Stärke gepaart mit ihrem eisernen Willen ermöglicht es ihr, hier am Gipfel zu überleben und die Überreste ihrer Brut zu bewachen. Die Thorignir sind ein prachtvoller Anblick, aber ich mag meine Drachen einfach etwas... knochiger. Sie muss als Erste sterben.\n\nErinnert Ihr Euch an die Stelle, an der wir uns getroffen haben? Die Mutter wacht über die Feuerschale dort, genau wie es der Geist auf dem Gipfel tat. Wenn wir sie entzünden, wird sie kommen.", sourceObjective = "Zündet Thorims Fanal am Thorimshorn an, um Daumyr zu erwecken. Besiegt sie und lasst sie dann wiederauferstehen.", completion = "Was für ein Auftritt, Todesgebieter.", sourceObjectiveStatus = "unverified-source-field" }
quests[44788] = { id = 44788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsstudie: Bestiarien von Azsuna" }
quests[44789] = { id = 44789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Wälle", description = "Auf die Schwächung ihrer Bodentruppen hat die Legion mit Verstärkung reagiert.\n\nUnsere Verbündeten haben einige dieser Dämonen am Himmel über der Rabenwehr gesichtet. Ich befürchte, dass sie dort eine Stellung einrichten wollen.\n\nNehmt diesen Hippogryphen und kundschaftet die Wälle aus. Wenn meine Befürchtung stimmt, möchte ich, dass Ihr diese Bedrohung umgehend ausschaltet.", sourceObjective = "Kundschaftet die dämonischen Truppen oben auf der Rabenwehr aus.", progress = "Neuigkeiten?", completion = "Unser Sieg hier ist mehr als verdient. Jetzt wo wir ihre Truppen dezimiert haben, können wir unsere Angriffe auf das Vorhutslager und die Monstrosität am Horizont ausweiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[44790] = { id = 44790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenfeuerprobe", description = "Wir haben keine Zeit mehr. Es wird berichtet, dass ein Grubenlord nach Meredil gekommen ist.\n\nIch habe schon einen Angriffstrupp ausgesandt. Wir dürfen nicht zulassen, dass dieser Dämon unserer Armee in die Flanke fällt oder Shal'Aran entdeckt. Es ist an der Zeit, diese Rekruten in einer echten Schlacht abzuhärten.\n\nTrefft Euch in Meredil mit unserer Streitmacht, kümmert Euch um den Dämon und stellt so sicher, dass unsere neue Armee nicht ihrer ersten Schlacht erliegt.", sourceObjective = "Tötet Rozzeleth in Meredil.", completion = "Gut gemacht. Manchmal lässt sich durch einen einzigen Sieg eine ganze Armee zusammenschweißen. Im Laufe der Zeit werden diese Rekruten andere ausbilden, sodass unsere Armee um ein Vielfaches größer wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[44799] = { id = 44799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichere Aufbewahrung" }
quests[44800] = { id = 44800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entgegen Magathas Willen", description = "Und? Worauf wartet Ihr? Gebt den Verdammnisstein her.", sourceObjective = "Sprecht mit Magatha Grimmtotem und bringt dann den Verdammnisstein zu Scharfseher Nobundo.", completion = "Der Verdammnisstein! Ich hielt ihn für eine Legende, doch hier ist er, direkt vor meinen Augen.\n\nSpürt Ihr die Macht, die er ausstrahlt? Wir dürfen ihn nur in ärgster Not nutzen, denn seine Macht fordert einen hohen Preis.\n\nGut, dass Ihr ihn nicht Magatha gegeben habt. In ihren Händen könnte er großen Schaden anrichten.\n\nBitte verwahrt ihn sicher, bis wir einen angemessenen Aufbewahrungsort für ihn vorbereitet haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[44801] = { id = 44801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung von Shal'Aran" }
quests[44802] = { id = 44802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Hilfe" }
quests[44803] = { id = 44803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Herr des Hauses", description = "Im Innern der Taschenuhr findet Ihr eine abgewetzte Notiz.\n\n\"Die nächste Gesellschaft findet in Morgans Grund statt und wird für Aufsehen sorgen! Folgende Gäste werden teilnehmen:\n\nLord Ference, er bevorzugt Rotwein.\nBaroness Mühlenstein, sie kommt nur, wenn es Käse gibt. Seltsame Frau.\nBaron Dreuger, ein sehr hungriger Mann, er freut sich über jede Art gut gewürzten Fleisches.\n\nWie immer werde ich die Glocke läuten, wenn ich Eure Hilfe benötige.\n\n- Medivh\"", sourceObjective = "Besorgt die aufgelisteten Dinge und bringt sie zum Friedhof außerhalb von Karazhan.", progress = "Was habt Ihr denn da?", completion = "Wie wundervoll! Ihr habt das Abendessen mitgebracht! Moroes hatte schon Sorge, er müsste seinen Meister enttäuschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44805] = { id = 44805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittendrin statt nur dabei" }
quests[44811] = { id = 44811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe ist auf dem Weg" }
quests[44812] = { id = 44812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit leerem Magen" }
quests[44813] = { id = 44813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienstörung" }
quests[44814] = { id = 44814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Zuflucht", description = "Mehr können wir hier nicht tun.\n\nBringen wir alle ins Boot und verschwinden wir, solange wir noch können.\n\nWir haben den anderen Zeit gewonnen, aber das war es auch schon.", sourceObjective = "Verlasst den Teufelsseelenvorstoß mit Delines Gondel.", completion = "Diese Leute verdanken ihr Leben Eurer Tapferkeit. Sie werden nie vergessen, welche Risiken wir auf uns genommen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[44815] = { id = 44815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbei mit der Kriecherei" }
quests[44816] = { id = 44816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andauernde Aussetzung" }
quests[44817] = { id = 44817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schwarm anstacheln" }
quests[44821] = { id = 44821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In höchster Not", description = "Die von Euch überbrachten schlechten Neuigkeiten vergrößern nur die Besorgnis, die der Rat ohnehin schon hatte.\n\nIch weiß, Ihr habt alle Hände voll zu tun mit dem Grabmal des Sargeras. Natürlich steht der Kampf um das Grabmal für uns weiterhin an erster Stelle, aber wir dürfen nicht davon ausgehen, dass die Legion töricht genug ist, sich nur auf brutale Gewalt zu verlassen. Sie ist weitaus gerissener.\n\nBitte, leiht uns Euer Ohr.", sourceObjective = "Sprecht mit dem Rat der Sechs im Purpursalon.", completion = "Also, was sagt Ihr? Seid Ihr bereit für eine Herausforderung?", sourceObjectiveStatus = "unverified-source-field" }
quests[44822] = { id = 44822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporale Untersuchungen", description = "Ich wusste ja, dass die Shal'dorei mit Zeitmagie experimentieren, doch das ist einfach nur unglaublich...\n\nElisande hat für unsere ganze Armee die Zeit angehalten!\n\nKommt, wir müssen mehr herausfinden. Vielleicht gibt es einen Weg, um den Zauber aufzuheben... oder wenigstens herauszufinden, wie er aufrechterhalten wird.", sourceObjective = "Untersucht zusammen mit Khadgar Elisandes Zeitzauber.", completion = "Dieses Mal haben wir Glück gehabt, doch wenn wir es erneut versuchten, setzen wir all unsere Leben für nichts aufs Spiel. Wir müssen einen anderen Weg finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[44823] = { id = 44823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumarbeiten in Donnertotem" }
quests[44825] = { id = 44825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irrwisch in den Weiden", description = "Irrwische sind die Geister unserer Nachtelfenbrüder, die eins mit dem Wald wurden. Aber ihr Verstand und ihre Sicht der Dinge sind nicht mehr dieselben wie zu ihren Lebzeiten.\n\nIhr solltet eine Verbindung mit diesem kleinen Irrwisch eingehen. Seht durch seine Augen, wenn er zu den verborgenen Teichen reist und Bäume wachsen lässt.", sourceObjective = "Leitet den Irrwisch zu den verborgenen Teichen, um 8 Bäume wachsen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44827] = { id = 44827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bürgertruppen", description = "Ich kann diese Zivilisten kaum dazu kriegen, in einer geraden Reihe zu stehen.\n\nSie sind untrainiert, undiszipliniert und unzureichend bewaffnet.\n\nTrotzdem müssen sie für die Schlacht bereit sein.\n\nKhadgar hat vorgeschlagen, dass wir uns zu Übungszwecken zur Rabenwehr nach Val'sharah begeben. Die auferstandenen Truppen von Lord Rabenkrone wissen wohl noch, wie man kämpft.\n\nGeht dorthin, <Held/Heldin>, dann werde ich Euch ein paar Lehrlinge als Unterstützung schicken.", sourceObjective = "Besiegt 20 Mitglieder von Rabenkrones Truppen in der Rabenwehr in Val'sharah.", completion = "Die Lehrlinge, denen Ihr geholfen habt, hören nicht auf, von Eurem Kampfgeschick zu schwärmen. Schon jetzt geben sie weiter, was Ihr ihnen gezeigt habt.\n\nIch bin für Eure Hilfe bei dieser Sache sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[44829] = { id = 44829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen Waffen", description = "So viele Rebellen wollen in der kommenden Schlacht helfen. Unser Volk ist willig, hat aber nicht die Mittel.\n\nEs braucht Waffen.\n\nKhadgar ließ es so klingen, als wäre die Festung der Rabenwehr randvoll mit Waffen.\n\nReist in die Festung und platziert diese Signalgeber auf einigen Waffenvorräten dort. Sobald Ihr sie platziert habt, kann ich die Waffen zu uns teleportieren.", sourceObjective = "Beschafft 3 Waffentruhen in der Rabenwehr in Val'sharah.", completion = "Diese Waffen werden uns im kommenden Konflikt gut dienen. Gut gemacht, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[44830] = { id = 44830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von den Toten lernen", description = "Wie ich höre, seid Ihr auf dem Weg zur Rabenwehr.\n\nEinst war sie das Heim des legendären Lord Rabenkrone, eines genialen Taktikers. Sein Wissen könnte genau das sein, was uns einen Vorteil gegenüber der Dämmerwache verschafft.\n\nWährend Ihr in der Rabenwehr seid, solltet Ihr Euch nach gut erhaltenen Büchern umsehen, die Rabenkrones Strategien beschreiben.", sourceObjective = "Beschafft 5 Bücher der Taktiken in der Rabenwehr in Val'sharah.", progress = "Was macht die Suche?", completion = "Ausgezeichnet. Das Wissen in diesen Büchern sollte sich in den kommenden Tagen als sehr nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44831] = { id = 44831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promenadenaufmischung", description = "Diese Leute sind uns fremd, ungeachtet unseres gemeinsamen Erbes. In den langen Jahren ihrer Abgeschiedenheit haben sie sich sehr verändert.\n\nWir müssen mehr über sie und ihre Fähigkeiten in Erfahrung bringen. Wir haben einen unserer Späher entsandt, um die Promenade zu infiltrieren und ihre Verteidigung auszuspionieren. Die Blutelfen haben das Gleiche getan, aber ich zweifle an ihrer Fähigkeit zur Diskretion.\n\nDie beiden hätten sich längst wieder melden sollen. Sucht sie und sorgt dafür, dass sie in Sicherheit gelangen oder wenigstens nicht umsonst gestorben sind.", sourceObjective = "Findet die Späher auf der Promenade.", completion = "Es tut gut zu wissen, dass sie noch leben. Ihr Wissen wird bei der kommenden Belagerung von unschätzbarem Wert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[44832] = { id = 44832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bresche erkunden", description = "Wenn Ly'leths Informationen stimmen, gibt es im Sanktum der Ordnung eine Bresche, die unseren einzigen Weg in die Nachtfestung darstellen könnte.\n\nMan wird sie mit Sicherheit magisch versiegelt haben. Geht mit Valtrois dorthin und beschützt sie, während sie das Siegel untersucht. Sie ist außergewöhnlich talentiert und ich bin fest davon überzeugt, dass sie jede Verzauberung brechen kann, die sich dort befinden mag.\n\nValtrois hat ihre eigenen Methoden, um in die Stadt zu gelangen, und wird Euch im Sanktum der Ordnung treffen.", sourceObjective = "Helft Valtrois unterhalb des Sanktums der Ordnung in Suramar.", completion = "Es scheint, als hätte Ly'leth recht gehabt. Dies ist ein Eingang zum Nachtbrunnen... und er ist gut geschützt. Doch nichts ist undurchdringlich.\n\nSehen wir uns einmal bei den Leylinien um, die diesen Schild mit Energie versorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44833] = { id = 44833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Siegels", description = "Der Nachtbrunnen ist so überladen, dass für dieses Siegel nichts mehr übrig blieb. Stattdessen zapfen sie die Macht der Leylinien an.\n\nIch habe eine Ihrer Machtquellen nach Kel'balor zurückverfolgt. Wir sollten uns sofort dorthinbegeben, damit ich herausfinden kann, wie man diese Barriere am besten ausschaltet.\n\nJa, natürlich habe ich \"wir\" gesagt. Ihr würdet doch nicht erwarten, dass ich ohne Leibwächter dorthingehen würde, oder?\n\nIch treffe Euch dort!", sourceObjective = "Untersucht das Leyliniengerät in Kel'balor im Purpurdickicht.", completion = "Valtrois hat mir alles erzählt. Sie arbeitet konzentriert daran, herauszufinden, wie wir diese Barriere ausschalten können.\n\nIch fürchte, vorerst bleibt uns nur zu warten. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[44834] = { id = 44834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nullifiziert", description = "Der Magus, der für die Verteidigung an diesem Ort verantwortlich ist, ist sehr mächtig. Vielleicht sogar zu mächtig für uns beide.\n\nGlücklicherweise wissen die Sin'dorei das ein oder andere über die Magie. Die Barriere des Magiers ist stark, doch wir sind clever.\n\nEr hat irgendwie genug Energie in seinen Stab kanalisiert, um eine weitere Reihe defensiver Portale zu befeuern, doch er behält ihn nicht bei sich. Bringt mir den Stab und eine Energiequelle von einem der Konstrukte. Damit sollte ich etwas erschaffen können, um den Schild zu deaktivieren.", sourceObjective = "Beschafft den geladenen Stab des Arkusformers und einen instabilen Konstruktkern für Sendath.", progress = "Wenn man das magische Gewebe bedenkt, ist es praktisch ein Kinderspiel. Ich sehe die Fehler schon nach wenigen Minuten des Studiums.", completion = "Ausgezeichnete Arbeit. Mit der Waffe haben wir ein passendes Behältnis, und die magische Signatur des Kerns ermöglicht eine Überbrückung...", sourceObjectiveStatus = "unverified-source-field" }
quests[44842] = { id = 44842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Zauber auf Schild trifft", description = "Da ist er: ein arkaner Nullifizierer! Mithilfe ihrer Waffe und der magischen Signaturen ließ sich der Zauber so verhüllen, dass er den Schild im Stile eines meisterhaften Zauberbrechers zerschmettern sollte.\n\nUnd jetzt zieht los und zeigt diesen Amateurzauberern, was es bedeutet, die Sin'dorei herauszufordern!", sourceObjective = "Benutzt den arkanen Nullifizierer, um Arkusformer Thorendis zu bezwingen.", completion = "Gut. Ohne ihn können wir jetzt eine stärkere Stellung aufbauen, sobald die Hauptstreitmacht eintrifft.", sourceObjectiveStatus = "unverified-source-field" }
quests[44843] = { id = 44843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallklärung", description = "Dieses Portal ist ein Problem. Damit können sie endlos Unterstützung herbeirufen.\n\nDas Tor scheint durch die Kristalle in der Nähe versorgt zu werden. Wenn wir die zerstören, können wir sie ganz schön zurückwerfen.", sourceObjective = "Zerstört 4 Portalkristalle.", completion = "Gute Arbeit. So bald werden sie das Portal nicht wieder öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44844] = { id = 44844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Portal abschalten", description = "Die Vernichtung der Kristalle wird sie vorübergehend aufhalten, doch es wird sinnlos sein, wenn wir uns nicht um die Person kümmern, die das Portal selbst kontrolliert.\n\nIch habe gehört, wie ihre Aufseherin Ingra herumgeschrien hat, dass sie mehr Energie braucht, damit sie die stärkeren Legionsleutnants durch das Tor bringen kann. Um das Portal endgültig zu schließen, müssen wir sie aufhalten.", sourceObjective = "Tötet Aufseherin Ingra.", completion = "Ein solch großes Portal wird sich nicht so bald wieder öffnen lassen. Ich würde sagen, das zählt als Schwächung ihrer Verteidigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[44845] = { id = 44845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hals- und Armbruch", description = "Die Aufrührer, die Ihr aufgeboten habt, hatten schlechte Neuigkeiten für mich, {name}.\n\nDie Elisande treu ergebenen Arkanisten haben den Arm der Magistrix reaktiviert. Das ist das mächtigste Konstrukt, das je zu bauen versucht wurde. Es geriet außer Kontrolle und zerstörte ein ganzes Stadtviertel, bevor es deaktiviert werden konnte. Sie müssen wirklich verzweifelt sein, wenn sie das gegen uns einsetzen.\n\nDie Späher haben es im Purpurdickicht im Norden ausgemacht. Wir dürfen nicht zulassen, dass es seine volle Kraft erreicht, wenn wir erfolgreich sein möchten.", sourceObjective = "Besiegt den Arm der Magistrix.", progress = "Wir müssen den Arm zerstören!", completion = "Die Invasion war fast gescheitert, bevor wir überhaupt damit angefangen haben. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[44846] = { id = 44846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir machen den Weg frei" }
quests[44847] = { id = 44847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direkt von der Quelle" }
quests[44848] = { id = 44848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ch 5 Available Tracking Quest" }
quests[44849] = { id = 44849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutensuche", description = "Helyas Kvaldir überfallen seit Jahrhunderten die Küsten Azeroths. Viele würdige Vrykul, die auserkoren waren, meine Valarjar zu werden, wurden gestohlen.\n\nJetzt, da ihre verfluchte Königin besiegt ist, können die in Helheim gefangenen Seelen endlich befreit werden, um sich uns anzuschließen!\n\nGeht mit Aerylia nach Helheim. Ich versichere Euch, sie wird Euch unversehrt wieder zurückbringen.", sourceObjective = "Bittet Aerylia darum, Euch nach Helheim zu geleiten.", completion = "Schärft Eure Sinne, {name}. Hier gibt es viele, die darauf aus sind, Eure Seele zu stehlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44850] = { id = 44850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut gerüstet sollt ihr sein...", description = "Die jüngsten Schlachten haben unsere Vorräte zur Neige gehen lassen und wir werden Waffen für unsere neuen Valarjar brauchen.\n\nDie Kvaldir verfügen aufgrund ihrer Raubzüge über Waffen, Rüstungen und andere Kriegsbeute im Überfluss und haben diese in gestohlenen Kisten gelagert.\n\nBeschlagnahmt alles, dessen Ihr habhaft werden könnt!", sourceObjective = "Durchsucht gestohlene Kisten nach 10 gestohlenen Schwertern und 10 gestohlenen Schilden.", progress = "Habt Ihr irgendwelche Vorräte gefunden, die wir in Helheim gebrauchen können, {name}?", completion = "Sehr gut. Die werden uns in den kommenden Kämpfen von großem Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[44853] = { id = 44853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melee DPS Chosen" }
quests[44854] = { id = 44854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AoE Chosen" }
quests[44856] = { id = 44856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz schön katzbürstig!" }
quests[44857] = { id = 44857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht dort, nicht dann, nicht jemals" }
quests[44858] = { id = 44858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollt Euch", sourceObjective = "Entfernt beleidigende Gegenstände aus den Kriegslagern der Elfen.", completion = "Danke, {name}. Jetzt, da unsere Streitkräfte Euch bei dieser Aufgabe gesehen haben, kommen sie hoffentlich zur Besinnung und hören mit diesen Schikanen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[44859] = { id = 44859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liadrins Befehl", description = "Shal'Aran ist zum Platzen voll mit Flüchtlingen und Rebellen. Im Prinzip haben wir jetzt eine Armee, doch weder Waffen noch Mana reichen aus, um alle zu wappnen und vor dem Verdorren zu bewahren.\n\nUnd nebenbei hat Lady Liadrin einen Haufen Anforderungen, für die ich nun wirklich keine Zeit habe.\n\nKönntet Ihr zu ihr gehen? Ihre wachsende Armee in Meredil ist schwer zu übersehen.", sourceObjective = "Sprecht mit Lady Liadrin in Meredil.", completion = "Ich kann Thalyssras Frustration nachempfinden.\n\nIch erinnere mich noch daran, wie ich meine erste Offensive gestartet habe. Ich schwöre, ich habe eine Woche lang weder gegessen noch geschlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44860] = { id = 44860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollt Euch", sourceObjective = "Entfernt beleidigende Gegenstände aus den Kriegslagern der Elfen.", completion = "Danke, {name}. Jetzt, da unsere Streitkräfte Euch bei dieser Aufgabe gesehen haben, kommen sie hoffentlich zur Besinnung und hören mit diesen Schikanen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[44861] = { id = 44861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewaffnung der Rebellen", description = "Die Rebellion der Nachtsüchtigen gewinnt an Anhängern, doch diese haben seit Ewigkeiten in keinem echten Krieg mehr gekämpft.\n\nVictoire und Silgryn geben ihr Bestes, um die Neuankömmlinge auszubilden, könnten aber erfahrene Hilfe brauchen.\n\nGeht zu ihnen und zeigt ihnen ein paar der Kampffähigkeiten, die Ihr Euch auf Euren Reisen angeeignet habt. Ich möchte, dass diese Nachtsüchtigen kampfbereit sind, wenn die Zeit kommt.", sourceObjective = "Sprecht mit Victoire in Meredil.", completion = "Jedes Mitglied der Dämmerwache hatte Jahrhunderte Zeit, seine Kampftechniken zu perfektionieren. Wir haben nicht so viel Zeit, diese Rebellen in eine gute Verfassung für den Kampf zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44862] = { id = 44862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewaffnung der Rebellen", description = "Die Rebellion der Nachtsüchtigen gewinnt an Anhängern, doch diese haben seit Ewigkeiten in keinem echten Krieg mehr gekämpft.\n\nVictoire und Silgryn geben ihr Bestes, um die Neuankömmlinge auszubilden, und könnten erfahrene Hilfe brauchen.\n\nGeht zu ihnen und zeigt ihnen ein paar der Kampffähigkeiten, die Ihr Euch auf Euren Reisen angeeignet habt. Diese Nachtsüchtigen müssen kampfbereit sind, wenn die Zeit kommt.", sourceObjective = "Sprecht mit Victoire in Meredil.", completion = "Jedes Mitglied der Dämmerwache hatte Jahrhunderte Zeit, seine Kampftechniken zu perfektionieren. Wir haben nicht so viel Zeit, diese Rebellen in eine gute Verfassung für den Kampf zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44863] = { id = 44863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich Luft verschaffen", description = "Um das Wissen für die Herstellung uralter Waffen wiederzuerlangen, benötigt man zunächst uralte Gaben.\n\nWenn Ihr lernen möchtet, wie man luftgeschmiedete Waffen herstellt, müsst Ihr Euch den Wesen stellen, die aus jener geboren wurden.\n\nBringt mir ihre Kerne. Dann werde ich Euch das Wissen zuteilwerden lassen, das Ihr sucht.", sourceObjective = "Sucht für Lunelli nach einem Kardinalhimmelskern, einem Kardinalsturmkern und einem Kardinalwindkern. Bringt die Steine zu ihr nach Shattrath, wenn Ihr sie alle zusammen habt.", progress = "Passt auf ihre Angriffe auf, denn Luft bemerkt man erst, wenn man sie schon auf der Haut spürt.", completion = "Die Luft, die Euch umgibt, verrät mir, dass Ihr siegreich zurückkehrt.\n\nHier ist das Wissen, nach dem Ihr sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[44864] = { id = 44864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Crusader" }
quests[44865] = { id = 44865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Butler von Berühmtheiten", description = "Eine gespenstische Dinnerparty steht an, alles ist bereit für das Festessen und die Dinnergäste.", sourceObjective = "Deckt den Tisch und beschwört Moroes.", completion = "Ich kann gar nicht glauben, dass es endlich vorbei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[44867] = { id = 44867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Vorstoß stoppen" }
quests[44868] = { id = 44868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung der Tapferkeit: Odyns Urteil", description = "Ihr habt Euch als würdig erwiesen, Helya herauszufordern. Mein Segen gewährt Euch die Macht, sie zu besiegen.", sourceObjective = "Bezwingt Helya im Schlachtzug \"Die Prüfung der Tapferkeit\".", completion = "Es ist geschafft. Helyas Herrschaft hat ein Ende, und jetzt können wir voranschreiten. Ihr habt heute Großes vollbracht, Champion. Zählt Euch zu den Helden in den Hallen der Tapferkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[44869] = { id = 44869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krallenkrawall", description = "Ich habe gerade eine Nachricht erhalten, dass die Brennende Legion den Schrein von Aviana angreift! Während die Druiden der Kralle sich hier Zeit lassen, um ihre Verteidigung zu planen und Strategien zu entwickeln, werden unsere Brüder und Schwestern an Ort und Stelle abgeschlachtet.\n\nIch kann nicht untätig sein, während mein Heimatschrein in Gefahr ist. Bitte, kommt mit mir, um mein Volk zu retten.", sourceObjective = "Benutzt das Portal auf dem Traumpfad, um Euch mit Thisalee am Schrein von Aviana auf dem Hyjal zu treffen.", completion = "Ich musste meine gesamte Willenskraft aufbieten, um mich nicht ohne Verstärkung mitten ins Gefecht zu werfen. Auf geht's!", sourceObjectiveStatus = "unverified-source-field" }
quests[44870] = { id = 44870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu stopfende Mäuler", description = "Wie Ihr sehen könnt, haben wir viele Flüchtlinge retten können. Aber leider eröffnet sich dadurch ein neues Problem.\n\nDie Frucht des Arcan'dor ist unsere Rettung, aber er trägt nicht genug Früchte, um alle zu heilen. Wir müssen noch eine Weile auf das Mana zurückgreifen, um die Flüchtlinge zu versorgen.\n\nValtrois glaubt, eine Lösung für das Problem gefunden zu haben. Bitte geht zu ihr und besprecht ihre Pläne mit ihr.", sourceObjective = "Sprecht mit Arkanistin Valtrois in Shal'Aran.", completion = "Gut, dass Ihr da seid. Ich könnte hier Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44871] = { id = 44871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 World - 850 - Special - Moroes 1" }
quests[44872] = { id = 44872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 World - 850 - Special - Moroes 2" }
quests[44873] = { id = 44873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oculeth ex Machina", description = "Ich habe einen Plan, Shal'Aran zu versorgen.\n\nJetzt, wo ich mich nicht mehr nach Mana verzehre, konnte ich die Leylinien in anderen Gegenden studieren. Ich habe einen Manawirbel in den Leylinien von Azsuna ausgemacht. Mir steht eine Menge Magie zur Verfügung, aber wir müssen die Leylinie persönlich aufsuchen, um die Energie korrekt nach Shal'Aran umzulenken.\n\nOculeth hat uns einen Transport zugesagt, aber ich brauche jemanden, der mir dabei hilft. Wollt Ihr mich vielleicht begleiten?", sourceObjective = "Sprecht mit Oculeth und lasst Euch nach Azsuna teleportieren.", completion = "Das war ein bisschen beängstigend. Manchmal bezweifle ich, dass Oculeth immer weiß, was er da tut.", sourceObjectiveStatus = "unverified-source-field" }
quests[44874] = { id = 44874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts für Leyen", description = "Zurück zur eigentlichen Aufgabe!\n\nNehmt diese Leylinienableiter. Wir können den Fluss durch die Resonanzenergien richtig ausrichten, doch dafür müsst Ihr sie an ganz bestimmten Orten präzise platzieren. Ich zeige Euch wo.\n\nEure Freundin hat sich einverstanden erklärt, uns zu... \"überwachen\". Wir können nur hoffen, dass sie uns nicht in die Quere kommt und die Arbeit den Profis überlässt.", sourceObjective = "Helft Arkanistin Valtrois beim Platzieren des Leylinienableiters.", completion = "Das war etwas nervtötender als nötig. Aber zumindest entsprachen meine Berechnungen annähernd ihren natürlichen Talenten...", sourceObjectiveStatus = "unverified-source-field" }
quests[44875] = { id = 44875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles im Fluss", description = "Es ist vollbracht, {name}! Nur noch ein kleiner Schritt und Shal'Aran wird so viel Mana erhalten, wie es nur brauchen kann.\n\nDurch den besseren Zugriff auf die Leylinie da unten kann ich das Energievorkommen so lösen, dass die Energie reibungslos durchfließt. Aufgrund des chaotischen Zustands dieser Leylinie werde ich all meine Konzentration benötigen, um die Energie umzulenken.\n\nIch muss Euch warnen, dass ich dadurch Aufmerksamkeit auf uns lenken werde. Ihr müsst mich beschützen, während ich die Prozedur beende.\n\nSagt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Beschützt Arkanistin Valtrois, während sie das Ritual abschließt.", completion = "Wir haben es geschafft. Shal'Aran wird keinen Mangel an Mana mehr zu beklagen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[44876] = { id = 44876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tanz mit Drachen", description = "Ich bin sehr beeindruckt, {name}.\n\nIhr und Eure Freundin konntet eine Leylinie instand setzen, obwohl Ihr noch nicht einmal Drachen seid!\n\nAber Ihr scheint davon erschöpft zu sein. Erlaubt mir, Euch nach Hause zu bringen.", sourceObjective = "Sprecht mit Stellagosa über einen Flug zurück nach Shal'Aran.", completion = "Ihr habt ein fulminantes Abenteuer erlebt. Aber glücklicherweise haben wir jetzt genug Mana für die Flüchtlinge. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44877] = { id = 44877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Nistplatz", description = "Himmelsfürst Schattenhain hat lange Zeit die Verteidigung des Schreins angeführt, aber er scheint langsam die Hoffnung zu verlieren. Er braucht ganz einfach etwas Feuerschutz!\n\nLasst uns diese Dämonen ausschalten und den Angriff zurückwerfen. Sie werden eine tödliche Überraschung erleben!", sourceObjective = "Tötet 15 Invasoren der Legion.", progress = "Immer ein gutes Gefühl, das Messer in einen Dämonenrücken zu stoßen!", completion = "Ha! Nimm das, Dämonenabschaum!", sourceObjectiveStatus = "unverified-source-field" }
quests[44879] = { id = 44879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowfeather Matriarch Tracking Q" }
quests[44880] = { id = 44880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbeak Matriarch Tracking Q" }
quests[44881] = { id = 44881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharptalon Matriarch Tracking Q" }
quests[44882] = { id = 44882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodgazer Matriarch Tracking Q" }
quests[44884] = { id = 44884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Smaragdgrünen Bucht" }
quests[44885] = { id = 44885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffbrüchige Überlebende", description = "Wir scheinen ein paar Verbündete hier an der Verheerten Küste zu haben.\n\nEine kleine Gruppe schiffbrüchiger Soldaten hat hier seit dem ersten Angriff ausgeharrt. Mit ihrer Entschlossenheit und ihrem Durchhaltevermögen sind sie eine wertvolle Unterstützung für uns.\n\nBegebt Euch zu ihrem Lager am Strand und bringt sie hierher. Sagt ihnen, dass Verstärkung eingetroffen ist und dass der Kampf gegen die Brennende Legion weitergeht.", sourceObjective = "Sprecht mit Rottenmeisterin Stahlzahn.", sourceObjectiveStatus = "unverified-source-field" }
quests[44886] = { id = 44886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerwünschte Beweise", description = "<Ihr findet den zersplitterten Überrest eines Teufelskristalls in Skovalds Faust. Er glüht immer noch vor dämonischer Energie.\n\nEs scheint, der Gottkönig wollte nicht, dass er gefunden wird. Enthielt er womöglich Gul'dans Nachricht an ihn?\n\nWenn irgendjemand hinter die Bedeutung des Kristalls kommen kann, dann ist es Khadgar.>", sourceObjective = "Bringt das Teufelskristallfragment zu Erzmagier Khadgar in Dalaran.", progress = "Grüße, {name}.\n\nHabt Ihr Gul'dans Nachricht an Skovald abfangen können?", completion = "Ihr glaubt also, Skovald wollte nicht, dass Ihr diesen Kristall entdeckt? Lasst mich mal sehen.\n\n<Khadgar betrachtet das Stück des Teufelskristalls und verfolgt die Machtlinien, die es durchziehen.>\n\nSo einen Kristall habe ich schon einmal gesehen. Sie werden benutzt, um die Befehle von den höchstrangigen Mitgliedern der Legion zu übermitteln.\n\nDas ist nicht gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[44887] = { id = 44887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle aufdecken", description = "Es scheint, als hätten die Meister der Legion geheime Befehle verschickt. Wenn sie ihren Plan vor uns verheimlichen wollen, muss es sich um eine ernste Bedrohung handeln.\n\nWir wissen, dass hochrangige Dämonen und ihre Verbündeten sich an mächtigen Orten sammeln. Höchstwahrscheinlich haben sie ähnliche Kristalle erhalten.\n\nVielleicht findet Ihr ja einen unbeschädigten Kristall oder genug Fragmente, um einen wiederherzustellen und herauszufinden, welches Ziel die Legion verfolgt.", sourceObjective = "Sammelt das Fragment der Bösartigkeit in der Rabenwehr (Mythisch), das Fragment der Macht in der Violetten Festung (Mythisch) und das Fragment der Folter im Verlies der Wächterinnen (Mythisch).", progress = "Wir müssen herausfinden, was die Legion plant.", completion = "Gut gemacht! Das war sicher nicht leicht.\n\nDas sollten genug Fragmente sein. Schauen wir mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[44888] = { id = 44888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avianas Anmut", description = "Wenn das nur eine Ablenkung war, wo ist dann die Hauptstreitmacht? Wer wird noch angegriffen? Wir müssen herausfinden, wer noch in Gefahr ist! Aviana wird es sicherlich wissen, denn sie hat ihre Augen überall.\n\nGehen wir sie fragen. Im Raum hinten im Schrein sollten wir Kontakt zu ihr aufnehmen können.", sourceObjective = "Kontaktiert Aviana im Schrein von Aviana.", completion = "Die Natur ist in großer Not, Sterblicher. Ihr müsst ihr helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44889] = { id = 44889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ressourcenverwaltung", description = "Jetzt, wo sich Helyas Horn in Eurem Besitz befindet, habt Ihr die Kontrolle über die Kvaldir. Mit ihren Talenten im Kampf könnten sie zur Abwechslung etwas Gutes für uns bewirken.\n\nIch habe meine Val'kyr Danica zur Verheerten Küste entsandt. Sie hat ein paar Legionsziele ausfindig gemacht, die vernichtet werden sollten.\n\nAerylia wird Euch dort hinschicken, sobald Ihr zum Aufbruch bereit seid.", sourceObjective = "Sprecht mit Aerylia, um zum Leidensweg an der Verheerten Küste zu reisen.", completion = "Gut, dass Ihr es hierhergeschafft habt, Schlachtenfürst {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44890] = { id = 44890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Azrok the Afflictor" }
