quests[44913] = { id = 44913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "recycelt mich", description = "Bezwingt Viz'aduum den Beobachter in Karazhan (Normal).", sourceObjective = "Bezwingt Viz'aduum den Beobachter in Karazhan auf dem Schwierigkeitsgrad 'Normal'.", sourceObjectiveStatus = "unverified-source-field" }
quests[44914] = { id = 44914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen: Der diebische Lehrling", description = "Die fokussierende Iris wurde aus den Tresoren Dalarans gestohlen! Der Dieb muss über beträchtliche magische Fertigkeiten verfügen, aber wir konnten ihn nicht aufspüren.\n\nGlücklicherweise aber hat der Dieb ein Schreiben seines Meisters fallen gelassen, in dem dieser von seinen \"Lehrlingsen\" spricht. Ich kenne nur einen, der seine Lehrlinge so bezeichnet: Erzmagier Xylem.\n\nIch möchte, dass Ihr die Sache untersucht. In Azshara findet Ihr seinen Turm, wo er seine Lehrlinge unterrichtet. Begebt Euch dorthin und findet heraus, was Xylem vorhat.", sourceObjective = "Reist zu Xylems Turm am Bärenkopf in Azshara.", completion = "Jemand hat die fokussierende Iris gestohlen und Ihr glaubt, dass Xylem dahintersteckt? Das könnte stimmen.\n\nEs ist kein Geheimnis, dass der Erzmagier immer auf der Suche nach Artefakten ist. Nach der Entdeckung eines antiken Zauberfolianten in den Ruinen der Legashi ist Xylem allerdings etwas... seltsam geworden. Ich fürchte, dieser Zauberfoliant beraubt ihn seines Verstandes.\n\nIch kann ein Treffen mit dem Erzmagier arrangieren. Mit etwas Glück könnt Ihr die Iris ohne Blutvergießen zurückholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44915] = { id = 44915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleider machen Lehrlingse", description = "Der Erzmagier hat sich vor Kurzem in seinem Turm eingeschlossen. Wenn Ihr dort hineinwollt, benötigt Ihr die Hilfe seiner Lehrlinge. Aber so, wie Ihr angezogen seid, wird das wohl nichts.\n\nXylem legt großen Wert auf... die Aufmachung. Und für seine Lehrlinge gilt die richtige Aufmachung als Rangabzeichen. Wenn sie Euch also helfen sollen, müsst Ihr wie <ein Ranghöherer/eine Ranghöhere> aussehen. Die Lehrlinge sind so drauf versessen, den Erzmagier zu beeindrucken, dass sie sogar um die besten Kleidungsstücke kämpfen.\n\nIhr versteht sicher, worauf ich hinauswill.", sourceObjective = "Besorgt einen extraordinären Hut, fein geschnittene Roben und einen prachtvollen Mantel von Raethas Morgenseher, Lobos und Phloem in Azshara.", progress = "Wie läuft's mit den Klamotten?", completion = "Ja, das müsste funktionieren.\n\nDamit sollten Euch die Lehrlinge außerhalb des Turms für einen Ranghöheren halten. So solltet Ihr an Informationen gelangen können, die Ihr benötigt, um an der Barriere vorbeizukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44917] = { id = 44917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Der Turm der Macht", description = "Eure Champions haben bemerkt, dass das Gebiet um Karazhan herum von der Legion angegriffen wird. Das verheißt nichts Gutes.\n\nGeht den Turm hinauf und besiegt alle, auf die Ihr dort trefft.", sourceObjective = "Bezwingt Viz'aduum den Beobachter in Karazhan.", progress = "Wie gestalten sich die Herausforderungen in Karazhan?", completion = "Konntet Ihr die bösen Mächte in Karazhan besiegen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44918] = { id = 44918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nachricht von unseren Feinden", description = "{name}! Diese Nachrichten von Ly'leth, die wir über die Terrasse hinweg zurückverfolgt haben... Wir konnten es zu der Zeit noch nicht wissen, aber wir wurden beobachtet.\n\nDieser Kristall wurde heute am frühen Morgen von einem Boten überbracht. <Sie deutet auf einen Kristall neben ihr.>\n\nDie darin enthaltene Nachricht ist nichts für schwache Nerven. Bisher hat sie niemand sonst gesehen, doch nach allem, was Ihr für uns getan habt, habt Ihr es Euch verdient.", sourceObjective = "Hört Euch Andaris' Nachricht in Shal'Aran an.", completion = "Ich weiß nicht, was uns erwartet, doch wir können nicht einfach nur rumsitzen, während Ly'leth vermisst wird.\n\nWir müssen sofort etwas tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[44919] = { id = 44919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Herausforderung unserer Feinde", description = "Bei einem könnt Ihr sicher sein, diese Nachricht werden wir nicht auf die leichte Schulter nehmen. Wir werden uns rasch um jede Bedrohung gegen unser Volk kümmern.\n\nWir müssen sofort zu dem Anwesen reisen und herausfinden, was mit Ly'leth geschehen ist.", sourceObjective = "Trefft Andaris am Anwesen der Lunastres in Suramar.", completion = "Die Verdorrten... so leicht besiegt.\n\nWir müssen eine Möglichkeit finden, um die Dämonenpaktmagie unwirksam zu machen. Wir können keinen Kampf riskieren, wenn unsere eigenen Leute gegen uns gewandt werden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[44920] = { id = 44920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles der Reihe nach", description = "Die Schutzbarriere des Turms kann nur aufgehoben werden, indem man die magischen Edelsteine in der richtigen Reihenfolge aktiviert. Und diese Reihenfolge ist nur Xylem und seinem inneren Lehrlingszirkel bekannt. Bislang ist es noch niemand anderem gelungen, den Code zu entziffern, und die Fehlversuche erwiesen sich zumeist als tödlich.\n\nDie angehenden Lehrlinge haben viel Zeit im Umfeld des Turms verbracht. Vielleicht haben einige von ihnen etwas gesehen oder gehört, was zu einer Lösung beitragen könnte.\n\nLasst uns um Eurer Sicherheit willen hoffen, dass sie über nützliche Informationen verfügen.", sourceObjective = "Sprecht am Bärenkopf mit Xylems Lehrlingen, um den Code zum Aufheben der Turmbarriere zu entschlüsseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[44921] = { id = 44921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsamer Wolf", description = "Meine Augen und Ohren fliegen über ganz Azeroth und tragen mir Kunde von vielerlei Dingen zu. Mein Verbündeter Goldrinn hat sich nach dem Tod von Varian Wrynn in die Grabhügel der Mondlichtung zurückgezogen, um zu trauern. Er konnte sich friedlich seinem Traum hingeben... bis jetzt.\n\nDämonen sind in die Grabhügel eingedrungen und haben viele weitere sterbliche Druiden getötet. Ihr müsst Euch aufmachen. Rettet Goldrinn! Rächt unsere Brüder und Schwestern! Nehmt meinen Schlüpfling Thisalee mit. Ihre Entschlossenheit und ihr Blutdurst sind in meinem Schwarm gern gesehen. Meine Unterstützung ist Euch gewiss.", sourceObjective = "Trefft Euch mit Thisalee Krähe auf der Mondlichtung.", completion = "Wenn sich Goldrinn im Traum befindet, ist er wehrlos! Wir müssen ihm helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[44922] = { id = 44922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Wintersturm", description = "Gleich da drüben scheint eine gute Stelle zu sein, auf die Ihr zielen könnt. Auf diesem Pfad müsstet Ihr bis ganz nach oben kommen.\n\nLaut meiner Informationen findet Ihr da oben Eure Drachen. Ich hoffe nur, dass sie überhaupt noch in der Lage sind, Euch zu helfen.", sourceObjective = "Hangelt Euch vom Turm hinüber und steigt dann zum Gipfel des Gebirgspfads hoch.", sourceObjectiveStatus = "unverified-source-field" }
quests[44923] = { id = 44923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ankunft der Helarjar: Vrekt" }
quests[44924] = { id = 44924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Erzmagier behelligen", description = "Die Barriere ist überwunden! Damit ist Erzmagier Xylem endlich in Reichweite!\n\nHoffentlich wird er kooperieren und die Iris aushändigen...", sourceObjective = "Stellt Erzmagier Xylem.", completion = "Wie ich befürchtet hatte, ist der Erzmagier bar jeder Vernunft... und jetzt ist er auch noch geflohen.\n\nIhr habt gute Arbeit geleistet und seine Lehrlinge von der Verderbnis befreit, aber der Kampf ist noch nicht vorüber.", sourceObjectiveStatus = "unverified-source-field" }
quests[44925] = { id = 44925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Auge zudrücken", description = "Wir haben Berichte von den Lehrlingen in Xylems Turm erhalten, dass sie die Überreste von Xylems Portal dazu nutzen konnten, seinen Aufenthaltsort festzustellen.\n\nWir haben Befehl vom Rat der Sechs, ein Portal direkt zu ihm zu öffnen. Allerdings ist die Magie, die er auf der anderen Seite kanalisiert, so mächtig, dass wir es nur sehr kurz offenhalten können.\n\nLehrling Joanna bat mich, Euch diese Nachricht zu überbringen, bevor Ihr fortfahrt. Sprecht mich an, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Kriegsrätin Victoria, um Euch zu Erzmagier Xylems Aufenthaltsort teleportieren zu lassen und ihn zu besiegen.", completion = "Ich muss mich bei Euch entschuldigen, {class}. Es war unverantwortlich von mir, mich des Zauberfolianten zu bedienen, und ich habe ganz Azeroth damit in Gefahr gebracht.\n\nDanke, dass Ihr nicht nur den bösen Schatten, der mich befallen hatte, vertrieben, sondern zudem auch mein Leben verschont habt.\n\nIch stehe zusammen mit ganz Azeroth in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[44926] = { id = 44926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich glaube, es hackt", description = "Der Aufbau dieser Klinge kommt Euch bekannt vor, aber Ihr könnt Euch nicht entsinnen, wo Ihr so etwas schon einmal gesehen haben könntet.\n\nVielleicht weiß jemand in Meißelgriff mehr über sie.", sourceObjective = "Zeigt die Axtklinge Hoddruc Klingenbeuger in Meißelgriff.\n\nBereitgestellter Gegenstand:", completion = "Aha! Ja, das Hackbeil kenn ich.\n\nDer Meister, der dieses Teil hergestellt hat, hat auch die berühmte Kahlholzhacke geschaffen. Vielleicht habt Ihr ja schon mal davon gehört.\n\nUnd wie es der Zufall will, weiß ich ebenfalls, wie man sie herstellt!", sourceObjectiveStatus = "unverified-source-field" }
quests[44927] = { id = 44927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein Gewicht in Stahl wert", description = "Hört zu, Ihr scheint mir jemand zu sein, der an einer Abschrift dieser Axtpläne interessiert sein könnte.\n\nDamit könnt Ihr im Auktionshaus wahrscheinlich ein paar gute Taler verdienen. Aber ich kann sie Euch nicht einfach so, also kostenlos, überlassen, <mein Lieber/meine Liebe>.\n\nWas ich aber gebrauchen könnte, wären noch ein paar von diesen Axtklingen. Die sind aus ziemlich gutem Stahl. Und keine Sorge, <mein Lieber/meine Liebe>, ich brauche wirklich nur ein paar davon...\n\nAlso, was sagt Ihr?", sourceObjective = "Sammelt 30 Axtklingen von Orcs und Ogern in der Brennenden Steppe. Bringt die Klingen zu Horddruc in Meißelgriff. wenn Ihr die geforderte Menge zusammen habt.", progress = "Wisst Ihr, ich muss eine ganze Ladung davon fertigstellen und in dieser Gegend liegt gutes Metall nicht gerade auf der Straße. Diese Klingen sind genau das, was ich suche.", completion = "Oh ho! Nun sieh sich mal einer diesen Haufen STAHL an!\n\nMit der Lieferung werde ich jetzt schon Ende der Woche fertig sein. Gut gemacht, Junge. Und hier sind die versprochenen Baupläne für die Hacke.", sourceObjectiveStatus = "unverified-source-field" }
quests[44928] = { id = 44928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendetwas stimmt hier nicht...", description = "Ich bin etwas besorgt, Champion.\n\nOft sind es nur Frotzeleien, doch die Kirin Tor mussten auch schon einige Kämpfe zwischen den Elfen beenden. Ich befürchte, etwas oder jemand beeinflusst sie möglicherweise.\n\nEure Verkleidung stammt von den Nachtgeborenen, ja? Von denen könnte man so etwas schon erwarten.\n\nGlücklicherweise hat Thalyssra mir viel darüber erklärt, wie die Illusion funktioniert. Ich glaube, dass dieser Kristall ihre Tarnung aufdecken könnte.\n\nSeht doch sicherheitshalber mal in den Lagern nach, ja?", sourceObjective = "Entfernt die Tarnung von 5 Spitzeln der Nachtgeborenen.", completion = "Wie ich befürchtet hatte. Sie denken jetzt hoffentlich länger darüber nach, bevor sie uns noch mehr Spione schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[44930] = { id = 44930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesminen: Ein Traum in Rot", description = "Arr, endlich! Ich bin hier schon seit Jahren gefangen und vollkommen allein. Es tut gut, mal 'ne andere Visage zu seh'n. Kann man Euch für 'n bisschen Hinterlist und Rache begeistern? Diese verdammten Schurken der Defias haben mich und meine Crew vor Jahren abgemurkst, bevor sie diese Höhle übernommen hab'n. Ich schlage ein paar Gegenmorde vor, um so 'ne Art Gleichstand zu erzielen. Bringt mir 'nen Beweis, dass Ihr genug von denen erledigt habt, um 'nen ganzen Schiffsfrachtraum zu füllen!", sourceObjective = "Sammelt 100 blutbeschmierte Bandanas der Defias für Kapitän Brombart ein.", progress = "Die süße Rache war das Warten wert. 'ne große Wahl hab ich ja auch nicht.", completion = "Ha ha ha! Ich hoffe, diese verdammten Halunken verrotten in ihrem eigenen Leichensaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[44931] = { id = 44931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "<Euer Schneefederjunges sieht Euch ängstlich an. Es verlässt sich wohl auf Eure Hilfe, um zu überleben und groß zu werden.>", sourceObjective = "Pflegt Eurer Schneefederjunges bis zum Erreichen von Stufe 25.", sourceObjectiveStatus = "unverified-source-field" }
quests[44932] = { id = 44932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Ein Ettinfuß in der Tür" }
quests[44933] = { id = 44933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Heulen in der Nacht" }
quests[44934] = { id = 44934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Gruselige Kriecher" }
quests[44935] = { id = 44935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Vergoldeter Wächter" }
quests[44936] = { id = 44936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Versorgungsrouten" }
quests[44937] = { id = 44937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Fokussierte Macht" }
quests[44938] = { id = 44938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Liebesentzug" }
quests[44939] = { id = 44939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Saat der Zerstörung" }
quests[44940] = { id = 44940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Wintersturm", description = "Gleich da drüben scheint eine gute Stelle zu sein, auf die Ihr zielen könnt. Auf diesem Pfad müsstet Ihr bis ganz nach oben kommen.\n\nLaut meiner Informationen findet Ihr da oben Eure Drachen. Ich hoffe nur, dass sie überhaupt noch in der Lage sind, Euch zu helfen.", sourceObjective = "Hangelt Euch vom Turm hinüber und steigt dann zum Gipfel des Gebirgspfads hoch.", sourceObjectiveStatus = "unverified-source-field" }
quests[44941] = { id = 44941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mit dem Rabenbären tanzt (UNBENUTZT)", description = "<Der Häuptling fordert die anderen Rabenbären auf, die Tributmaterialien zusammenzutragen, und weist in Richtung des Ritualkreises draußen.>\n\nKrah! Krah-krah!\n\n<Offensichtlich möchte er, dass Ihr ihm folgt.>", sourceObjective = "Helft den Rabenbären der Schwarzfedern, das Tributritual durchzuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44943] = { id = 44943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist ja klauenhaft!" }
quests[44944] = { id = 44944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aura der Ungewissheit", description = "Noch kennen wir zwar nicht die Absichten der Legion, doch wenn wir Eure Funde untersucht haben, werden wir dahinterkommen.", sourceObjective = "Helft Khadgar, die Geheimnisse hinter den Fragmenten zu enträtseln.", completion = "Es ist an der Zeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44948] = { id = 44948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneefederaufzucht", description = "<Euer Schneefederjunges sieht Euch ängstlich an. Es verlässt sich wohl auf Eure Hilfe, um zu überleben und groß zu werden.>", sourceObjective = "Pflegt Eurer Schneefederjunges bis zum Erreichen von Stufe 25.", progress = "Krächz?", completion = "<Das Junge scheint Euch jetzt ein wenig mehr zu vertrauen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44949] = { id = 44949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch von Menschen", description = "<Ihr habt bemerkt, dass Euer Schneefederjunges immer, wenn Menschen in der Nähe sind, zittert. Anscheinend hat es große Angst vor ihnen. Vielleicht solltet Ihr es irgendwo hinbringen, wo es eine Menge Menschen gibt, damit es sich an den Geruch gewöhnen kann.>", sourceObjective = "Bringt Euer Schneefederjunges zur Güldenen Rose in Sturmwind.", completion = "<Das Junge scheint nun mit dem Anblick und den Geräuschen einer Menschenstadt besser zurechtzukommen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44950] = { id = 44950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Nordfalkeneulen", description = "<Euer Schneefederjunges scheint ganz aufgeregt zu sein, wenn Ihr Euch anderen Kleintieren nähert. Dies gilt insbesondere für die Falkeneulen vom Hochberg. Es plustert sein Gefieder auf und krächzt laut, sobald eine in der Nähe ist. Anscheinend verspürt Euer Junges einen angeborenen Jagdinstinkt.> \n\n<Ihr müsst wohl mit Eurem Falkosaurier auf die Jagd gehen.>", sourceObjective = "Lasst Euer Schneefederjunges 3 Nordfalkeneulen am Hochberg bezwingen.", completion = "<Das Junge scheint mit seinen Siegen ziemlich zufrieden zu sein und macht es sich gemütlich. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44951] = { id = 44951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tank Chosen" }
quests[44952] = { id = 44952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfelstiefen: Juwel der Tiefen", description = "Willkommen in der Ewigen Warte. Habt Ihr vielleicht Interesse an einer neuen Waffe?\n\nIhr müsst wissen, ich verkaufe hier in meinem bescheidenen Laden nicht nur Gliedmaßenvernichtungswaffen. Auch mit Juwelen kenne ich mich aus.\n\nVielleicht können wir beide dahingehend ja ins Geschäft kommen, denn es gibt da eine Art Edelstein, auf die ich schon lange ein Auge geworfen habe. Ich habe ein paar außergewöhnliche Schmiedepläne in meinem Sortiment, die Euch vielleicht interessieren und die ich Euch als Gegenleistung für Eure... äh... Hilfe anbieten könnte.\n\nNun zu den Einzelheiten...", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und beschafft Euch einen Kern von Bael'Gar, einen Kern von Roccor, eine Essenz von Incendius und eine Essenz von Magmus. Sobald Ihr alle vier Materialien zusammen habt, müsst Ihr sie in der Schwarze Schmiede am tiefsten Punkt der Schwarzfelstiefen in der Nähe des Eingangs zum Geschmolzenen Kern miteinander kombinieren. Bringt dann den Schwarzfelsrubin zu Wixxrak in der Ewigen Warte.", progress = "Keine einfache Sache. Gerade deshalb ist das Juwel ja so selten, versteht Ihr?", completion = "Aber hallo, das nenne ich mal einen RUBIN! Von diesen Rubinen habe ich in meinem ganzen Leben bisher nur einen einzigen gesehen und jetzt habe ich einen.\n\nIch sage Euch, der macht mich noch stinkreich!\n\nAber äh... jetzt zu Eurer Bezahlung. Hier sind die Pläne, von denen ich gesprochen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[44953] = { id = 44953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete am Hochberg", description = "<Euer Schneefederjunges gibt ein tiefes, zwitscherndes Grummeln von sich, wenn Ihr Donnertotem dicht passiert.> \n\n<Die Hochbergstämme versuchten sofort, die Falkosaurier aus ihrem Territorium zu vertreiben. Euer Junges muss sie für eine Bedrohung für den Schwarm halten, und das Grummeln ist wahrscheinlich ein Versuch, Euch zu beschützen.>\n\n<Zeigt Eurem Falkosaurier, dass Ihr gemeinsam mit den Hochbergstämmen zusammenarbeiten könnt.>", sourceObjective = "Schließt 5 Weltquests am Hochberg in Begleitung Eures Schneefederjungen ab.", progress = "<Euer Schneefederjunges traut der Sache gar nicht.>", completion = "<Das Junge trillert beim Anblick von Donnertotem. Das ist schon eine große Verbesserung! Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44954] = { id = 44954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Team Schneefeder", description = "<Euer Schneefederjunges sieht Euch an und stößt eine Art krächzendes Bellen aus. Es scheint etwas zusammen mit Euch unternehmen zu wollen!>\n\n<Damit Euer Junges etwas lernt, muss es vor dem Beginn eines Kampfs an Eurer Seite und das erste Haustier sein, mit dem Ihr in den Kampf zieht, und darf nicht im Kampf sterben.>", sourceObjective = "Schließt 3 Haustierkampfweltquests auf den Verheerten Inseln mit Eurem Schneefederjungen ab.", completion = "<Das Junge stößt Euch sanft mit seinem Kopf an und trillert. Anscheinend unternimmt es sehr gerne Sachen mit Euch! Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44955] = { id = 44955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besucherin in Shal'Aran", description = "Jemand ist in Shal'Aran eingetroffen, während Ihr in der Stadt wart. Sie hat unmissverständlich nach Euch gefragt.\n\nIch habe weder ihr Gesicht noch ihre Stimme erkennen können, aber sie schien mir aufrichtig und vertrauenswürdig zu sein.\n\nSie wartet draußen vor der Höhle. Sucht sie auf, um den Beweggrund ihres Kommens zu erfahren.", sourceObjective = "Trefft Euch mit der Fremden außerhalb von Shal'Aran.", completion = "Sie sah gut aus. Der Arcan'dor stellt wahrlich ein Wunder für unser Volk dar.\n\nSie wird uns in den kommenden Kämpfen eine wertvolle Verbündete sein. Silgryn wird sich gut um sie kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[44956] = { id = 44956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tödliche Beute", description = "<Nachdem er Euch in letzter Zeit bei Haustierkämpfen beigestanden hat, scheint Euer Schneefederfalkosaurier deutlich stärker an Euren Kampffertigkeiten interessiert zu sein. Vielleicht kann er ja das ein oder andere lernen, wenn er Euch beim Kampf gegen einen mächtigen Gegner zusieht.>", sourceObjective = "Schließt 1 seltene Eliteweltquest in Begleitung Eures Schneefederjungen ab.", progress = "<Euer Schneefederjunges ist bereit zu lernen!>", completion = "<Das Junge sieht Euch voller Bewunderung an. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44957] = { id = 44957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Stachelschwanzbiber", description = "<Euer Schneefederjunges interessiert sich in letzter Zeit sehr für Biberspuren. Es muss eine neue Beute entdeckt haben.>", sourceObjective = "Bezwingt 3 Stachelschwanzbiber am Hochberg mit Eurem Schneefederjungen.", progress = "<Euer Schneefederjunges ist bereit für die Jagd.>", completion = "<Das Junge scheint nach dem Sieg über die Biber Selbstvertrauen gewonnen zu haben und macht es sich gemütlich. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44958] = { id = 44958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unfreundliche Fraktion", description = "<Als Ihr vor Kurzem an einem Mitglied der anderen Fraktion vorbeigegangen seid, ist Eure Schneefeder ihm furchtlos entgegengeeilt. Sie versteht wohl nicht, dass es sich um den Feind handelt. Ihr solltet es ihr besser beibringen, bevor etwas Schlimmes passiert.>", sourceObjective = "Schließt 3 PvP-Weltquests in Begleitung Eures Schneefederjungen ab.", progress = "<Euer Schneefederjunges mag die andere Fraktion wohl ein wenig zu sehr.>", completion = "<Das Junge lässt jetzt ein tiefes Zischen hören, wenn Ihr an einem Mitglied der gegnerischen Fraktion vorbeikommt. Ein voller Erfolg! Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44959] = { id = 44959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneefederbande", description = "<Euer Schneefederjunges wühlt ständig in Eurem Rucksack herum und bringt dort alles durcheinander. Es krächzt laut, wenn Ihr ihn ihm abnehmt, und stößt mit dem Kopf nach Euch. Vielleicht solltet Ihr ihm einen eigenen kleinen Rucksack spendieren?>", sourceObjective = "Kauft einen winzigen Rucksack von Susana Averoy in Dalaran für Euer Schneefederjunges.", progress = "<Euer Schneefederjunges sieht Euch fragend an.>", completion = "<Ihr verspürt eine besondere Verbindung zwischen Euch und dem Jungen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44960] = { id = 44960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Schlickmuschelschlurfer", description = "<Euer Schneefederjunges hat sich mit einigen der anderen fliegenden Haustiere angefreundet. Die Schar ist darauf aus, ein paar Schnecken am Hochberg zu jagen.>", sourceObjective = "Bezwingt 3 Schlickmuschelschlurfer am Hochberg mit Eurem Schneefederjungen und 2 Flughaustieren.", completion = "<Das Junge ist von seinen Fähigkeiten stärker überzeugt. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44961] = { id = 44961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamworkunterricht: Naraxas", description = "<Trotz des Sieges ist es bedenklich, dass Euer Schneefederjunges seine Verbündeten im Kampf angekrächzt und nach ihnen gepickt hat. Vielleicht solltet Ihr ihm zeigen, wie gutes Teamwork funktioniert.>", sourceObjective = "Bezwingt Naraxas in Neltharions Hort am Hochberg in Begleitung Eures Schneefederjungen.", completion = "<Das Junge sieht aus, als hätte es vielleicht einen Teil der Lektion verinnerlicht. Auf jeden Fall hat ihm die Reise Spaß gemacht. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44962] = { id = 44962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Korallenrückenmauschler", description = "<Euer Schneefederjunges verhält sich misstrauisch gegenüber den Elementarhaustieren in Eurer Menagerie. Wenn es mit ihnen zurechtkommen soll, muss es lernen, an ihrer Seite zu kämpfen. Vielleicht hilft es, wenn Ihr gemeinsam eine neue Beute verfolgt.>", sourceObjective = "Bezwingt 3 Korallenrückenmauschler am Hochberg mit Eurem Schneefederjungen und 2 Elementarhaustieren.", completion = "<Das Junge ist nun viel gelassener in der Nähe von Elementaren. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44963] = { id = 44963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranged DPS Chosen" }
quests[44964] = { id = 44964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich lasse das einfach mal hier", description = "Valtrois hat einen Plan für die Energiebarriere des Sanktums ersonnen.\n\nWichtige Standorte innerhalb des Arkus in ganz Suramar bieten die dafür erforderliche Energie. Die Energiedisruptoren, die sie angefertigt hat, lösen gleichzeitig und aus der Ferne die Verbindungen und lassen die Barriere so zusammenbrechen.\n\nNehmt diese Geräte und installiert sie an den Leylinien. Kehrt dann hierhin zurück, damit der Überraschungsangriff auf das Sanktum beginnen kann.", sourceObjective = "Platziert Energiedisruptoren bei den Energiequellen in Teloth'aran, Kel'balor und Elor'shan in Suramar.", completion = "Die Vorbereitungen sind fast abgeschlossen. Oculeth wird bald bereit sein, um uns zu teleportieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[44965] = { id = 44965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealth Chosen" }
quests[44966] = { id = 44966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healer Chosen" }
quests[44967] = { id = 44967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamworkunterricht: Ursoc", description = "<Euer Schneefederjunges hat es sich angewöhnt, in Stresssituationen gegen andere Haustiere zu kämpfen. Es muss lernen, auch unter Druck und im Kampf gegen große Tiere einen kühlen Kopf zu bewahren. Es sollte helfen, wenn Ihr ihm ein episches Beispiel für Teamwork gegen ein großes Tier zeigt.>", sourceObjective = "Besiegt Ursoc im Smaragdgrünen Alptraum in Begleitung Eures Schneefederjungen.", completion = "<Das Junge strahlt Euch nach dem Sieg über einen so schrecklichen Gegner stolz an. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44968] = { id = 44968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randale im Team mit Schneefeder", description = "<Sieht so aus, als wäre Euer Schneefederjunges bereit, sich mit Euch in ein paar neue Kämpfe zu stürzen, um zu zeigen, was es über Teamwork gelernt hat. Wenn Ihr es mit neuen Verbündeten zusammen anweisen würdet, wäre dies ein ausgezeichneter Test seiner Fähigkeiten.>", sourceObjective = "Schließt 3 Haustierkampf-Weltquests mit Eurem Schneefederjungen und 2 untoten Haustieren ab.", completion = "<Das Junge sieht nach diesem Sieg sehr stolz aus und putzt sich. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44969] = { id = 44969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneefederwiedersehen", description = "<In letzter Zeit verhält sich Euer Schneefederjunges lethargisch. Es scheint deprimiert zu sein. Vielleicht solltet Ihr mit ihm zum Ort seiner Geburt zurückkehren?>", sourceObjective = "Bringt das Schneefederjunge zurück zum Nebelufer am Hochberg.", sourceObjectiveStatus = "unverified-source-field" }
quests[44970] = { id = 44970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dual Boss Chosen" }
quests[44971] = { id = 44971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch von Orcs", description = "<Ihr habt bemerkt, dass Euer Schneefederjunges immer zittert, wenn Orcs in der Nähe sind. Anscheinend hat es große Angst vor ihnen. Vielleicht solltet Ihr es irgendwo hinbringen, wo es eine Menge Orcs gibt, damit es sich an den Geruch gewöhnen kann.>", sourceObjective = "Bringt Euer Schneefederjunges zum Gebrochenen Hauer in Orgrimmar.", completion = "<Das Junge scheint nun mit dem Anblick und den Geräuschen einer Orcstadt besser zurechtzukommen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44973] = { id = 44973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düsterschnabelaufzucht", description = "<Euer Düsterschnabeljunges scheint sich nicht ganz darüber im Klaren zu sein, was es anstellen sollte. Es verlässt sich wohl auf Eure Hilfe, um zu überleben und groß zu werden.>", sourceObjective = "Pflegt Eurer Düsterschnabeljunges bis zum Erreichen von Stufe 25.", progress = "Krächz!", completion = "<Das Junge stolziert glücklich und angeberisch herum. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44974] = { id = 44974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch von Zwergen", description = "<Ihr habt bemerkt, dass Euer Düsterschnabeljunges immer, wenn Zwerge in der Nähe sind, zittert. Anscheinend hat es große Angst vor ihnen. Vielleicht solltet Ihr es irgendwo hinbringen, wo es eine Menge Zwerge gibt, damit es sich an den Geruch gewöhnen kann.>", sourceObjective = "Bringt Euer Düsterschnabeljunges zur Steinfeuertaverne in Eisenschmiede.", completion = "<Das Junge scheint nun mit dem Anblick und den Geräuschen einer Zwergenstadt besser zurechtzukommen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44975] = { id = 44975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch von Tauren", description = "<Ihr habt bemerkt, dass Euer Düsterschnabeljunges immer zittert, wenn Tauren in der Nähe sind. Anscheinend hat es große Angst vor ihnen. Vielleicht solltet Ihr es irgendwo hinbringen, wo es eine Menge Tauren gibt, damit es sich an den Geruch gewöhnen kann.>", sourceObjective = "Bringt Euer Düsterschnabeljunges zum Gasthaus von Donnerfels.", completion = "<Das Junge scheint nun mit dem Anblick und den Geräuschen einer Taurenstadt besser zurechtzukommen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44976] = { id = 44976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Rosentaipan", description = "<Euer Düsterschnabeljunges scheint ganz aufgeregt zu sein, wenn Ihr Euch anderen Kleintieren nähert. Dies gilt insbesondere für die Rosentaipane aus Sturmheim. Es krächzt laut und rammt seinen Schnabel in den Boden, sobald einer in der Nähe ist. Anscheinend verspürt Euer Junges einen angeborenen Jagdinstinkt.> \n\n<Ihr müsst wohl mit Eurem Falkosaurier auf die Jagd gehen.>", sourceObjective = "Bezwingt 3 Rosentaipane in Sturmheim mit Eurem Düsterschnabeljungen.", completion = "<Das Junge scheint mit seinen Siegen ziemlich zufrieden zu sein. Es klammert sich an Euer Bein und wartet darauf, dass Ihr Euch setzt und es auf Euren Schoß hopsen kann. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44977] = { id = 44977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete in Sturmheim", description = "<Euer Düsterschnabeljunges scharrt im Boden und starrt finster einen der Valarjar an, der mehr als zehn Mal so groß ist.>\n\n<Die Valarjar müssen die Falkosaurier als willkommene neue Fleischquelle angesehen und sie sofort zu jagen begonnen haben. Sie sind zwar auf den Verheerten Inseln eine neue Spezies, aber sie fürchten bereits die Einwohner von Sturmheim.>\n\n<Zeigt Eurem Falkosaurier, dass Ihr gemeinsam mit den Valarjar zusammenarbeiten könnt.>", sourceObjective = "Schließt 5 Weltquests in Sturmheim in Begleitung Eures Düsterschnabeljungen ab.", progress = "<Euer Düsterschnabeljunges traut der Sache gar nicht.>", completion = "<Das Junge versteckt sich nicht mehr hinter Euch, wenn Stürme in Sturmheim toben. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44978] = { id = 44978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Team Düsterschnabel", description = "<Euer Düsterschnabeljunges beißt Euch. Es scheint etwas zusammen mit Euch unternehmen zu wollen!>\n\n<Damit Euer Junges etwas lernt, muss es vor dem Beginn eines Kampfs an Eurer Seite und das erste Haustier sein, mit dem Ihr in den Kampf zieht, und darf nicht im Kampf sterben.>", sourceObjective = "Schließt 3 Haustierkampfweltquests auf den Verheerten Inseln mit Eurem Düsterschnabeljungen ab.", completion = "<Das Junge knabbert aufgeregt an Euren Füßen. Anscheinend unternimmt es sehr gerne Sachen mit Euch! Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44979] = { id = 44979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düstere Beute", description = "<Euer Düsterschnabelfalkosaurier will unbedingt mit Euch in den Kampf ziehen und mehr darüber erfahren, wie man tödliche Kreaturen besiegt. Vielleicht kann er ja das ein oder andere lernen, wenn er Euch beim Kampf gegen einen mächtigen Gegner zusieht.>", sourceObjective = "Schließt 1 seltene Eliteweltquest in Begleitung Eures Düsterschnabeljungen ab.", progress = "<Euer Düsterschnabeljunges ist bereit, zu lernen!>", completion = "<Das Junge sieht Euch sehr interessiert an. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44980] = { id = 44980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Winzige Erscheinung", description = "<Euer Düsterschnabeljunges scheint Beute sehen zu können, die Euch verborgen bleibt, und starrt manchmal stundenlang die Wand an. Es muss eine neue Beuteart gefunden oder den Schnabel zu tief in den Met gesteckt haben.>", sourceObjective = "Besiegt 3 winzige Erscheinungen in Sturmheim mit Eurem Düsterschnabeljungen.", completion = "<Das Düsterschnabeljunge hat offensichtlich keinerlei Angst vor Geistern. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44981] = { id = 44981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unfreundliche Fraktion", description = "<Als Ihr vor Kurzem an einem Mitglied der anderen Fraktion vorbeigegangen seid, hat Euer Düsterschnabel ihn angekrächzt, um Nahrung zu erbetteln. Er versteht wohl nicht, dass es sich um den Feind handelt. Ihr solltet es ihm besser beibringen, bevor etwas Schlimmes passiert.>", sourceObjective = "Schließt 3 PvP-Weltquests in Begleitung Eures Düsterschnabeljungen ab.", completion = "<Das Junge kratzt aggressiv am Boden, wenn Ihr an einem Mitglied der gegnerischen Fraktion vorbeikommt. Ein voller Erfolg! Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44982] = { id = 44982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düsterschnabelbande", description = "<Euer Düsterschnabeljunges plustert sich auf und knurrt Euch an, um seine Dominanz zu zeigen. Es ist wohl etwas enttäuscht, dass Ihr nicht eingeschüchtert zusammenzuckt. Vielleicht möchte es sich als ausgewachsener Falkosaurier verkleiden und es erneut versuchen.>", sourceObjective = "Kauft falsche Zähne vom Aufziehgehilfen in Dalaran für Euer Düsterschnabeljunges.", progress = "<Euer Düsterschnabeljunges sieht Euch fragend an.>", completion = "<Ihr verspürt eine besondere Verbindung zwischen Euch und dem Jungen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44983] = { id = 44983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Goldadlerjunges", description = "<Euer Düsterschnabeljunges hat sich mit einigen der anderen fliegenden Haustiere angefreundet. Die Schar ist darauf aus, ein paar Adler aus Sturmheim zu jagen.>", sourceObjective = "Bezwingt 3 Goldadlerjunge in Sturmheim mit Eurem Düsterschnabeljungen und 2 fliegenden Haustieren.", completion = "<Das Junge baut sich ein kleines Nest aus Adlerfedern und macht es sich darin gemütlich. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44984] = { id = 44984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamworkunterricht: Fenryr", description = "<Euer Düsterschnabeljunges ist den anderen fliegenden Haustieren bei den letzten gemeinsamen Kämpfen scheu ausgewichen. Vielleicht solltet Ihr ihm zeigen, wie gutes Teamwork funktioniert.>", sourceObjective = "Besiegt Fenryr in den Hallen der Tapferkeit in Sturmheim in Begleitung Eures Düsterschnabeljungen.", completion = "<Das Junge hat einen großen Bausch Wolfspelz für sein Nest gesammelt. Ihr wisst nicht so recht, wo es ihn versteckt hatte. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44985] = { id = 44985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Sturmschlagbiber", description = "<Euer Düsterschnabeljunges betrachtet misstrauisch jede laute Maschine, an der Ihr vorbeigeht. Ihr beginnt Euch zu fragen, ob etwas zwischen dem Jungen und einem mechanischen Haustier vorgefallen ist. Wenn es mit ihnen zurechtkommen soll, muss es lernen, an ihrer Seite zu kämpfen. Vielleicht hilft es, wenn Ihr gemeinsam eine neue Beute verfolgt.>", sourceObjective = "Besiegt 3 Sturmschlagbiber in Sturmheim mit Eurem Düsterschnabeljungen und 2 mechanischen Haustieren.", completion = "<Das Junge ist nun viel gelassener gegenüber Maschinen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44986] = { id = 44986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamworkunterricht: Krosus", description = "<Euer Düsterschnabeljunges krächzt laut und wird panisch, wenn sich große Wesen in der Nähe befinden. Und das sogar, wenn sie friedlich sind. Es muss lernen, den Belastungen standzuhalten, selbst wenn es Kreaturen gegenübersteht, die viele Male größer sind. Es sollte helfen, wenn Ihr ihm ein herausragendes Beispiel für Teamwork gegen ein gigantisches Monster zeigt.>", sourceObjective = "Besiegt Krosus in der Nachtfestung in Begleitung Eures Düsterschnabeljungen.", completion = "<Das Junge knurrt Euch besitzergreifend an. Es scheint, als wäre es... stolz? Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44987] = { id = 44987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randale im Team mit Düsterschnabel", description = "<Sieht so aus, als wäre Euer Düsterschnabeljunges bereit, sich mit Euch in ein paar neue Kämpfe zu stürzen, um zu zeigen, was es über Teamwork gelernt hat. Wenn Ihr es mit neuen Verbündeten zusammen anweisen würdet, wäre dies ein ausgezeichneter Test seiner Fähigkeiten.>", sourceObjective = "Schließt 3 Haustierkampf-Weltquests mit Eurem Düsterschnabeljungen und 2 humanoiden Haustieren ab.", completion = "<Das Junge hat aus irgendeinem Grund noch immer Energie und rennt weg, um mit den anderen Tieren zu spielen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44988] = { id = 44988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düsterschnabelwiedersehen", description = "<In letzter Zeit gibt Euer Düsterschnabeljunges immer wieder ein leises, trauriges Krächzen von sich. Es scheint deprimiert zu sein. Vielleicht solltet Ihr mit ihm zum Ort seiner Geburt zurückkehren?>", sourceObjective = "Bringt das Düsterschnabeljunge zum Möwenfels in Sturmheim.", sourceObjectiveStatus = "unverified-source-field" }
quests[44989] = { id = 44989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfkrallenaufzucht", description = "<Euer Scharfkrallenjunges zittert noch, während es sich neben Euch setzt. Es sieht Euch mit großen und weit offenen Augen entgegen. Es verlässt sich wohl auf Eure Hilfe, um zu überleben und groß zu werden.>", sourceObjective = "Pflegt Eurer Scharfkrallenjunges bis zum Erreichen von Stufe 25.", completion = "<Das Junge zittert nicht mehr und hält sich auch nicht mehr an Euch fest. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44990] = { id = 44990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutstarreraufzucht", description = "<Euer Blutstarrerjunges betrachtet Euch neugierig. Es neigt seinen Kopf zur Seite und pfeift leise. Es verlässt sich wohl auf Eure Hilfe, um zu überleben und groß zu werden.>", sourceObjective = "Pflegt Eurer Blutstarrerjunges bis zum Erreichen von Stufe 25.", completion = "<Das Junge sieht stark und selbstsicher aus. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44991] = { id = 44991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch von Draenei", description = "<Ihr habt bemerkt, dass Euer Blutstarrerjunges immer zittert, wenn Draenei in der Nähe sind. Anscheinend hat es große Angst vor ihnen. Vielleicht solltet Ihr es irgendwo hinbringen, wo es eine Menge Draenei gibt, damit es sich an den Geruch gewöhnen kann.>", sourceObjective = "Bringt Euer Blutstarrerjunges zum Gasthaus der Exodar.", completion = "<Das Junge scheint nun mit dem Anblick und den Geräuschen einer Draeneistadt besser zurechtzukommen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44992] = { id = 44992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch von Nachtelfen", description = "<Ihr habt bemerkt, dass Euer Scharfkrallenjunges immer zittert, wenn Nachtelfen in der Nähe sind. Anscheinend hat es große Angst vor ihnen. Vielleicht solltet Ihr es irgendwo hinbringen, wo es eine Menge Nachtelfen gibt, damit es sich an den Geruch gewöhnen kann.>", sourceObjective = "Bringt Euer Scharfkrallenjunges zum Gasthaus von Darnassus.", completion = "<Das Junge scheint nun mit dem Anblick und den Geräuschen einer Nachtelfenstadt besser zurechtzukommen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44993] = { id = 44993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch von Blutelfen", description = "<Ihr habt bemerkt, dass Euer Blutstarrerjunges immer zittert, wenn Blutelfen in der Nähe sind. Anscheinend hat es große Angst vor ihnen. Vielleicht solltet Ihr es irgendwo hinbringen, wo es eine Menge Blutelfen gibt, damit es sich an den Geruch gewöhnen kann.>", sourceObjective = "Bringt Euer Blutstarrerjunges zum Gasthaus von Silbermond in Silbermond.", completion = "<Das Junge scheint nun mit dem Anblick und den Geräuschen einer Blutelfenstadt besser zurechtzukommen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44994] = { id = 44994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch von Untoten", description = "<Ihr habt bemerkt, dass Euer Scharfkrallenjunges immer zittert, wenn Verlassene in der Nähe sind. Anscheinend hat es große Angst vor ihnen. Vielleicht solltet Ihr es irgendwo hinbringen, wo es eine Menge Verlassene gibt, damit es sich an den Geruch gewöhnen kann.>", sourceObjective = "Bringt Euer Scharfkrallenjunges zum Gasthaus von Unterstadt.", completion = "<Das Junge scheint nun mit dem Anblick und den Geräuschen einer Stadt der Verlassenen besser zurechtzukommen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44995] = { id = 44995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Quellwasserläufer", description = "<Euer Scharfkrallenjunges scheint ganz aufgeregt zu sein, wenn Ihr Euch anderen Kleintieren nähert. Dies gilt insbesondere für die Quellwasserläufer von Val'sharah. Es plustert sein Gefieder auf und kratzt am Boden, sobald einer in der Nähe ist. Anscheinend verspürt Euer Jungtier einen angeborenen Jagdinstinkt.> \n\n<Ihr müsst wohl mit Eurem Falkosaurier auf die Jagd gehen.>", sourceObjective = "Besiegt 3 Quellwasserläufer in Val'sharah mit Eurem Scharfkrallenjungen.", completion = "<Das Junge scheint mit seinen Siegen ziemlich zufrieden zu sein und stupst Euch liebevoll mit seinem Kopf an. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44996] = { id = 44996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Gebildeter Manafresser", description = "<Euer Blutstarrerjunges scheint ganz aufgeregt zu sein, wenn Ihr Euch anderen Kleintieren nähert. Dies gilt insbesondere für die gebildeten Manafresser von Azsuna. Es gibt ein merkwürdiges leises Gackern von sich und breitet seine Flügel aus, sobald einer in der Nähe ist. Anscheinend verspürt Euer Jungtier einen angeborenen Jagdinstinkt.> \n\n<Ihr müsst wohl mit Eurem Falkosaurier auf die Jagd gehen.>", sourceObjective = "Besiegt 3 gebildete Manafresser in Azsuna mit Eurem Blutstarrerjungen.", completion = "<Das Junge scheint mit seinen Siegen ziemlich zufrieden zu sein und gackert Euch glücklich an. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44997] = { id = 44997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete in Val'sharah", description = "<Euer Scharfkrallenjunges weigert sich stur, Val'sharah zu betreten, als Ihr Euch nähert.>\n\n<Obwohl sie die Natur verehren, müssen die Traumweber auch das Gleichgewicht der Natur bewahren und begannen daher mit einer aggressiven Ausmerzung der Falkosaurier, als klar wurde, wie sehr sie sich verbreitet hatten. Es hat vermutlich gesehen, wie die Druiden von Val'sharah einige Mitglieder seiner Schar getötet haben.>\n\n<Zeigt Eurem Falkosaurier, dass Ihr gemeinsam mit den Traumwebern zusammenarbeiten könnt.>", sourceObjective = "Schließt 5 Weltquests in Val'sharah in Begleitung Eures Scharfkrallenjungen ab.", progress = "<Euer Scharfkrallenjunges traut der Sache gar nicht.>", completion = "<Das Junge zittert nicht mehr, wenn es sich in die dichte Belaubung von Val'sharah begibt. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44998] = { id = 44998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete in Azsuna", description = "<Euer Blutstarrerjunges gibt ein verängstigtes Kreischen von sich, als Ihr Azsunas Geister in der Nähe spürt.>\n\n<Die Geister der Elfen von Azsuna kommen Eurem Haustier sicher merkwürdig und widernatürlich vor. Vermutlich hat es aus reinem Instinkt vor ihnen Angst.>\n\n<Zeigt Eurem Falkosaurier, dass Ihr gemeinsam mit den Geistern von Farondis' Hofstaat zusammenarbeiten könnt.>", sourceObjective = "Schließt 5 Weltquests in Azsuna in Begleitung Eures Blutstarrerjungen ab.", completion = "<Die Geister in Azsuna erwecken bei dem Jungen jetzt eher Neugierde als Furcht. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44999] = { id = 44999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Team Scharfkralle", description = "<Euer Scharfkrallenjunges flattert aufgeregt mit seinen Flügeln und krächzt Euch an. Es scheint etwas zusammen mit Euch unternehmen zu wollen!>\n\n<Damit Euer Junges etwas lernt, muss es vor dem Beginn eines Kampfs an Eurer Seite und das erste Haustier sein, mit dem Ihr in den Kampf zieht, und darf nicht im Kampf sterben.>", sourceObjective = "Schließt 3 Haustierkampfweltquests auf den Verheerten Inseln mit Eurem Scharfkrallenjungen ab.", completion = "<Das Junge gibt ein lautes \"Baruu!\" von sich. Anscheinend unternimmt es sehr gerne Sachen mit Euch! Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45000] = { id = 45000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Team Blutstarrer", description = "<Euer Blutstarrerjunges rennt im Kreis um Euch herum und bringt Euch fast zum Stolpern. Es scheint etwas zusammen mit Euch unternehmen zu wollen!>\n\n<Damit Euer Junges etwas lernt, muss es vor dem Beginn eines Kampfs an Eurer Seite und das erste Haustier sein, mit dem Ihr in den Kampf zieht, und darf nicht im Kampf sterben.>", sourceObjective = "Schließt 3 Haustierkampfweltquests auf den Verheerten Inseln mit Eurem Blutstarrerjungen ab.", completion = "<Das Junge strahlt Euch an. Anscheinend unternimmt es sehr gerne Sachen mit Euch! Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45001] = { id = 45001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörerische Beute", description = "<Euer Scharfkrallenfalkosaurier beobachtet Euch aufmerksam, während Ihr kämpft. Er scheint an Euren Kampffertigkeiten interessiert zu sein. Vielleicht kann er ja das ein oder andere lernen, wenn er Euch beim Kampf gegen einen mächtigen Gegner zusieht.>", sourceObjective = "Schließt 1 seltene Eliteweltquest in Begleitung Eures Scharfkrallenjungen ab.", completion = "<Das Junge ist von Euren Fähigkeiten stärker überzeugt. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45002] = { id = 45002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Beute", description = "<Euer Blutstarrerfalkosaurier zittert noch immer scheu, wenn eine mächtige Kreatur in der Nähe ist. Es würde sicher sein Selbstbewusstsein stärken, wenn er sehen würde, wie Ihr eine solche Kreatur bezwingt.>", sourceObjective = "Schließt 1 seltene Eliteweltquest in Begleitung Eures Blutstarrerjungen ab.", completion = "<Das Junge krächzt Euch an. Möglicherweise ein Kompliment? Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45003] = { id = 45003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Terrorlarve", description = "<Euer Scharfkrallenjunges sucht in letzter Zeit verzweifelt nach Würmern in Val'sharah. Es muss eine neue Beute entdeckt haben.>", sourceObjective = "Besiegt 3 Terrorlarven in Val'sharah mit Eurem Scharfkrallenjungen.", progress = "<Euer Scharfkrallenjunges ist bereit für die Jagd.>", completion = "<Das Junge schluckt eine der Larven herunter und sieht Euch dann kurz an, als ob sie ihm gleich wieder hochkommen würde. Ihr solltet es besser im Auge behalten. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45004] = { id = 45004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Königsfederjungvogel", description = "<Euer Blutstarrerjunges flattert aufgeregt mit den Flügeln und reibt seinen Schnabel an Baumstämme in Azsuna. Es muss eine neue Beute entdeckt haben.>", sourceObjective = "Besiegt 3 Königsfederjungvögel in Azsuna mit Eurem Blutstarrerjungen.", progress = "<Euer Blutstarrerjunges ist bereit für die Jagd.>", completion = "<Der Sieg über ein anderes fliegendes Haustier hat das Selbstbewusstsein Eures Blutstarrers mächtig gestärkt. Es wird eine Weile dauern, bis das Junge sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45005] = { id = 45005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unsympathische Fraktion", description = "<Als Ihr vor Kurzem an einem Mitglied der anderen Fraktion vorbeigegangen seid, wollte Eure Scharfkralle mit dessen Haustier spielen. Sie versteht wohl nicht, dass es sich um den Feind handelt. Ihr solltet es ihr besser beibringen, bevor etwas Schlimmes passiert.>", sourceObjective = "Schließt 3 PvP-Weltquest in Begleitung Eures Scharfkrallenjungen ab.", progress = "<Euer Scharfkrallenjunges mag die andere Fraktion wohl ein wenig zu sehr.>", completion = "<Das Junge rennt nun hinter Euch her, wenn Ihr an einem Mitglied der gegnerischen Fraktion vorbeikommt. Ein voller Erfolg! Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45006] = { id = 45006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ungünstige Fraktion", description = "<Als Ihr vor Kurzem an einem Mitglied der anderen Fraktion vorbeigegangen seid, hat Euer Blutstarrer neugierig an seinem Rucksack geschnüffelt. Er versteht wohl nicht, dass es sich um den Feind handelt. Ihr solltet es ihm besser beibringen, bevor etwas Schlimmes passiert.>", sourceObjective = "Schließt 3 PvP-Weltquests in Begleitung Eures Blutstarrerjungen ab.", progress = "<Euer Blutstarrerjunges mag die andere Fraktion wohl ein wenig zu sehr.>", completion = "<Das Junge plustert sich nun auf, wenn Ihr an einem Mitglied der gegnerischen Fraktion vorbeikommt. Ein voller Erfolg! Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45007] = { id = 45007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfkrallenbande", description = "<Euer Scharfkrallenjunges rennt bei jedem Gasthausbesuch instinktiv in die Küche und richtet mit Pfannen und Töpfen ein reines Chaos an. Es legt sich meist in herumstehendes Geschirr, vor allem, wenn es schmutzig ist. Vielleicht könntet Ihr sein Verhalten korrigieren, indem Ihr ihm sein eigenes Besteck beschafft.>", sourceObjective = "Kauft einen dreckigen Löffel von Mel Lynchen in Dalaran für Euer Scharfkrallenjunges.", progress = "<Euer Scharfkrallenjunges sieht Euch fragend an.>", completion = "<Ihr verspürt eine besondere Verbindung zwischen Euch und dem Jungen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45008] = { id = 45008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutstarrerbande", description = "<Euer Blutstarrerjunges liebt es wohl, sich in Blumen herumzuwälzen. Eure Schlussfolgerung ist, dass die Schar früher blühende Pflanzen suchte, um essbare Früchte zu entdecken. Es würde sich sicher sehr freuen, wenn es eine ganz eigene besondere Blume hätte!>", sourceObjective = "Kauft eine purpurfarbene Blüte von Aerith Schlüsselblume in Dalaran für Euer Blutstarrerjunges.", progress = "<Euer Blutstarrerjunges sieht Euch fragend an.>", completion = "<Ihr verspürt eine besondere Verbindung zwischen Euch und dem Jungen. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45009] = { id = 45009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Umbraringelschwanz", description = "<Euer Scharfkrallenjunges hat sich mit einigen der anderen fliegenden Haustiere angefreundet. Die Schar ist darauf aus, ein paar Waschbären aus Val'sharah zu jagen.>", sourceObjective = "Besiegt 3 Umbraringelschwänze in Val'sharah mit Eurem Scharfkrallenjungen und 2 fliegenden Haustieren.", completion = "<Das Junge zieht an einem sich ablösenden Nagel. Der wird bald nachgewachsen sein. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45010] = { id = 45010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Halbwüchsiger Krabbelrücken", description = "<Euer Blutstarrerjunges hat sich mit einigen der anderen fliegenden Haustiere angefreundet. Die Schar ist darauf aus, ein paar Krabben aus Azsuna zu jagen.>", sourceObjective = "Besiegt 3 halbwüchsige Krabbelrücken in Azsuna mit Eurem Blutstarrerjungen und 2 fliegenden Haustieren.", completion = "<Das Junge leckt seine Wunden. Es ist verletzt, aber zufrieden. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45011] = { id = 45011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamworkunterricht: Dresaron", description = "<Euer Scharfkrallenjunges interessiert sich nicht besonders für Eure anderen Haustiere und ignoriert sie im Kampf meist. Vielleicht solltet Ihr ihm zeigen, wie gutes Teamwork funktioniert.>", sourceObjective = "Besiegt Dresaron im Finsterherzdickicht in Val'sharah in Begleitung Eures Scharfkrallenjungen.", progress = "<Euer Scharfkrallenjunges blickt Euch an und erwartet Anweisungen.>", completion = "<Das Junge sieht erschöpft aus und schläft sofort ein. Es scheint, als hätte es einen Alptraum. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45012] = { id = 45012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamworkunterricht: Serpentrix", description = "<Obwohl Ihr gesiegt habt, hat Euer Blutstarrerjunges die anderen Haustiere an wichtigen Momenten im Kampf abgelenkt. Vielleicht solltet Ihr ihm zeigen, wie gutes Teamwork funktioniert.>", sourceObjective = "Bezwingt Serpentrix im Auge Azsharas in Azsuna in Begleitung Eures Blutstarrerjungen.", completion = "<Das Junge glüht leicht magisch. Wo ist es denn jetzt schon wieder gewesen? Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45013] = { id = 45013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Talfalter", description = "<Euer Scharfkrallenjunges weigert sich unnachgiebig, in die Nähe von Wasser zu gehen. Es krächzt und kratzt am Boden, sobald Ihr selbst Euch hineinwagt. Vielleicht würde es seine Ängste überwinden, wenn es mit ein paar aquatischen Haustieren zusammenarbeiten würde. Vielleicht hilft es, wenn Ihr gemeinsam eine neue Beute verfolgt.>", sourceObjective = "Besiegt 3 Talfalter in Val'sharah mit Eurem Scharfkrallenjungen und 2 aquatischen Haustieren.", completion = "<Das Junge ist nun viel gelassener in der Nähe von Wasser. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45014] = { id = 45014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdlektion: Teufelsspinne", description = "<Bei jedem Gasthausbesuch klettert Euer Junges auf die Möbel und weigert sich den Boden zu berühren. Es hüpft wackelig von einem Möbelstück zum nächsten und verursacht meist eine große Sauerei. Ihr wisst, dass dies mit einer schlechten Erfahrung mit Flöhen zusammenhängen könnte. Wenn Ihr mit ihm und ein paar Kleintierhaustieren neue Beute jagt, würde es vielleicht seine Furcht überwinden.>", sourceObjective = "Besiegt 3 Teufelsspinnen in Azsuna mit Eurem Blutstarrerjungen und 2 Kleintierhaustieren.", completion = "<Das Junge ist nun viel gelassener gegenüber Insekten. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45015] = { id = 45015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamworkunterricht: Xavius", description = "<Euer Scharfkrallenjunges hat es sich angewöhnt, in Euren Rucksack zu kriechen, wenn Ihr Euch sehr mächtigen Wesen nähert. Es muss lernen, selbst im Angesicht der schlimmsten Alpträume einen kühlen Kopf zu bewahren. Es sollte helfen, wenn Ihr ihm ein herausragendes Beispiel für Teamwork gegen einen furchterregenden Gegner zeigt.>", sourceObjective = "Besiegt Xavius im Smaragdgrünen Alptraum in Begleitung Eures Scharfkrallenjungen.", completion = "<Das Junge betrachtet Euch eher zurückhaltend. Es scheint von Eurer Macht ein wenig eingeschüchtert zu sein. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45016] = { id = 45016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamworkunterricht: Skorpyron", description = "<Euer Blutstarrerjunges knurrt und faucht große Tiere an, ohne an seine eigene Sicherheit zu denken. Es muss lernen, dass es nur in einer Gruppe wirklich sicher ist. Es sollte helfen, wenn Ihr ihm ein episches Beispiel für Teamwork gegen ein großes Tier zeigt.>", sourceObjective = "Besiegt Skorpyron in der Nachtfestung in Begleitung Eures Blutstarrerjungen.", progress = "<Euer Blutstarrerjunges blickt Euch an und erwartet Anweisungen.>", completion = "<Das Junge kaut nachdenklich auf einem Stück des großen Skorpions herum. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45017] = { id = 45017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randale im Team mit Scharfkralle", description = "<Sieht so aus, als wäre Euer Scharfkrallenjunges bereit, sich mit Euch in ein paar neue Kämpfe zu stürzen, um zu zeigen, was es über Teamwork gelernt hat. Wenn Ihr es mit neuen Verbündeten zusammen anweisen würdet, wäre dies ein ausgezeichneter Test seiner Fähigkeiten.>", sourceObjective = "Schließt 3 Haustierkampf-Weltquests mit Eurem Scharfkrallenjungen und 2 magischen Haustieren ab.", completion = "<Das Junge sieht erschöpft aus und verbringt nach dem Sieg einige Zeit damit, einfach nur zu trinken. Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45018] = { id = 45018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randale im Team mit Blutstarrer", description = "<Sieht so aus, als wäre Euer Blutstarrerjunges bereit, sich mit Euch in ein paar neue Kämpfe zu stürzen, um zu zeigen, was es über Teamwork gelernt hat. Wenn Ihr es mit neuen Verbündeten zusammen anweisen würdet, wäre dies ein ausgezeichneter Test seiner Fähigkeiten.>", sourceObjective = "Schließt 3 Haustierkampf-Weltquests mit Eurem Blutstarrerjungen und 2 Wildtierhaustieren ab.", completion = "<Das Junge sieht recht satt aus. Was hat es bloß gegessen? Es wird eine Weile dauern, bis es sich von diesem Abenteuer erholt hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45019] = { id = 45019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfkrallenwiedersehen", description = "<In letzter Zeit frisst Euer Scharfkrallenjunges nicht besonders gut. Es scheint deprimiert zu sein. Vielleicht solltet Ihr mit ihm zum Ort seiner Geburt zurückkehren?>", sourceObjective = "Bringt das Scharfkrallenjunge zu den Tiefgrünen Klippen von Val'sharah.", sourceObjectiveStatus = "unverified-source-field" }
quests[45020] = { id = 45020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutstarrerwiedersehen", description = "<In letzter Zeit trinkt Euer Blutstarrerjunges nicht mehr. Es scheint deprimiert zu sein. Vielleicht solltet Ihr mit ihm zum Ort seiner Geburt zurückkehren?>", sourceObjective = "Bringt das Blutstarrerjunge zu Alluvanons Delta in Azsuna.", sourceObjectiveStatus = "unverified-source-field" }
quests[45021] = { id = 45021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbekannte Antworten", description = "Habt Ihr auch Jubekas verändertes Verhalten bemerkt? Ich weiß, dass sie nicht die herzlichste aller Hexenmeisterinnen ist, aber ich befürchte, dieser Tage ist sie noch zurückgezogener als sonst.\n\nIch vermute, dass sich ihre Gedanken um Kanrethad, den einstigen Anführer des Rates, drehen. Jubeka hatte sich stets verpflichtet gefühlt, seine Verbannung unter allen Umständen aufrechtzuerhalten, bis die Brennende Legion sie gefangen nahm.\n\nSein Schicksal ist unbekannt und das scheint sie zu sorgen. Zuletzt sagte sie mir, dass sie seine Gegenwart in Azsuna spüren würde. Lasst sie diesen Weg nicht allein gehen.", sourceObjective = "Findet Jubeka Schattenbrecher in Azsuna.", completion = "Shinfel hätte Euch nicht von meinen Zweifeln erzählen sollen. Dies ist allein meine Bürde.\n\nAber dennoch bin ich froh, dass Ihr da seid, denn meine Befürchtungen scheinen sich zu bewahrheiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45022] = { id = 45022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "3+ Targets Chosen" }
quests[45023] = { id = 45023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hybrid Chosen" }
quests[45024] = { id = 45024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kult keulen", description = "Die Anziehungskraft von Kanrethad ist mächtig. Auch wenn er nicht in dieser Welt zugegen ist, suchen einige doch um jeden Preis seine Nähe, um an seiner Macht teilzuhaben.\n\nEin Gefangener sagte mir, eine Gruppe solcher Fanatiker solle hier in Faronaar unermüdlich daran arbeiten, Kanrethad zurückzubringen.\n\nDas dürfen wir nicht zulassen, {name}. Findet ihren Unterschlupf und tötet so viele von ihnen wie möglich.\n\nIch werde hierbleiben und versuchen, so viel wie möglich über ihre Absichten herauszufinden.", sourceObjective = "Begebt Euch zur Teufelsfeuergrotte und tötet Mitglieder des Kults der Grünen Flamme.", progress = "Wir dürfen nicht zulassen, dass diese Fanatiker Kanrethad zurückbringen!", completion = "Kann das wirklich sein? Ist ein klitzekleiner Funken meines Freundes in diesem widerwärtigen Dämon erhalten geblieben?", sourceObjectiveStatus = "unverified-source-field" }
quests[45025] = { id = 45025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Raub der Quelle der Macht", description = "Das hier ist ein wirklich gesprächiger Gefangener, {name}. Er hat mir erzählt, dass der Kult der Grünen Flamme Teufelsenergie einsetzt, um Kanrethad aus der Verbannung zurückzuholen.\n\nIn ihrem Unterschlupf laden sie Teufelskristalle auf, in denen sich eine große Menge Teufelsmagie speichern lässt. Ohne eine entsprechend große Menge Energie werden sie ihren Plan nämlich nicht umsetzen können.\n\nStehlt ihnen die Teufelskristalle, aber zerstört sie nicht. Für solch mächtige Objekte haben auch wir immer eine Verwendung.", sourceObjective = "Sammelt 5 Teufelskristalle ein.", progress = "Habt Ihr die Teufelskristalle beschaffen können?", completion = "Wie immer gute Arbeit, Netherfürst. Dadurch sollten wir ein bisschen Zeit gewonnen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[45026] = { id = 45026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsenergieentsorgung", description = "Schon bald wird Kanrethads Verbannung aufgehoben sein und er wird in unsere Welt zurückkehren.\n\nWir müssen ihn und seine Macht um jeden Preis von der Legion fernhalten.\n\nWenn mein alter Freund noch irgendwo da drinsteckt, können wir ihn vielleicht zurückbringen.\n\nDie erbeuteten Kristalle können Teufelsenergie absorbieren, sodass wir damit die verderbende Magie aufnehmen können, die Kanrethad unter Kontrolle hält.\n\nAber dazu müssen wir sie zunächst entleeren. Macht Euch die Kraft der Kristalle zunutze und verwendet die gespeicherte Energie dazu, ein paar Dämonen zu töten.", sourceObjective = "Macht Euch die Kraft der Teufelskristalle zunutze und entleert ihre Energien, indem Ihr mit ihnen in Faronaar Dämonen tötet.", progress = "Habt Ihr die Kristalle entleeren können?", completion = "Ich danke Euch, Netherfürst. Ich werde diese Kristalle sicher verwahren, bis sie wieder gebraucht werden.\n\nWenn wir Kanrethad finden, werden wir bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[45027] = { id = 45027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Verheerten Küste", description = "Wie es scheint, haben Kanrethads pervertierte Anhänger mit ihrem Ritual an der Verheerten Küste begonnen.\n\nWir müssen umgehend handeln. Wir dürfen nicht zulassen, dass die Brennende Legion Kanrethad als Waffe einsetzt.\n\nUnsere Akolythen sind bereit, ein Beschwörungsritual an der Verheerten Küste durchzuführen, wenn Ihr so weit seid.", sourceObjective = "Begebt Euch zur Verheerten Küste.", completion = "Ihr seid da, Netherfürst! Schnell! Wir müssen uns beeilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45028] = { id = 45028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanrethads Schicksal", description = "Ich kann es fühlen, <Netherfürst/Netherfürstin>! Kanrethad ist hier! Seine Anhänger haben ein Lager am nahe gelegenen Pass errichtet und führen gerade ein Ritual durch, um ihn zurückzuholen.\n\nSchnell, nehmt diese Teufelskristalle. Platziert sie in einem Kreis um Kanrethad herum.\n\nIn der richtigen Anordnung verbinden sich die Kristalle und beginnen, die Teufelsenergie zu absorbieren.\n\nUnd jetzt geht, bevor es zu spät ist!", sourceObjective = "Verwendet die Teufelskristalle, um Kanrethad die Teufelsenergie zu entziehen.", completion = "Seit dem Tag, an dem ich mein Versprechen erfüllte und Kanrethad verbannte, war mir das Herz schwer. Ich hätte nie gedacht, es noch erleben zu dürfen, dass Kanrethad zu uns zurückkehrt.\n\nIch danke Euch, Netherfürst. Ihr habt mir die Bürde der Schuld genommen und gleichzeitig dafür gesorgt, dass sich die Legion nicht eines der unseren bemächtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45029] = { id = 45029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon's Vengeance - Intro Complete" }
quests[45030] = { id = 45030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsgravierter Knochen", description = "<Dieser Knochen ist übersäht mit komplexen Runen, die nur mithilfe teuflischer Magie in die Oberfläche geätzt worden sein können.>\n\n<Jemand von den Kirin Tor in Dalaran wäre sicherlich daran interessiert.>", sourceObjective = "Findet jemanden, der an dem teufelsgravierten Knochen interessiert ist. Ihr vermutet, dass Ihr am besten bei den Kirin Tor in Dalaran mit Eurer Suche beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45032] = { id = 45032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Wind" }
quests[45033] = { id = 45033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Infernostein", description = "<Während der Stein dem ungeübten Auge wie ein unbedeutendes Stück Teufelsschutt erscheinen mag, erkennt Ihr ihn als einen der Katalysatoren, mit denen die Regeneration der stärksten Legionskrieger im Nether beschleunigt wird.>\n\n<Was er hier in Azeroth zu suchen hat, ist schwer einzuschätzen. Vielleicht können die Kirin Tor in Dalaran Euch helfen, mehr darüber herauszufinden?>", sourceObjective = "Findet jemanden, der Euch mehr über den Infernostein erzählen kann. Ihr vermutet, dass Ihr am besten bei den Kirin Tor in Dalaran mit Eurer Suche beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45034] = { id = 45034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuert die Kanonen ab!", description = "Von so einem verdammten Schiffbruch lasse ich mich nicht unterkriegen. Diese verwarzten, stinkenden Dämonensäcke werden sich noch wundern, wenn sie glauben, mich aufhalten zu können.\n\n<Keeshan hustet etwas Salzwasser aus und wischt sich dann den Mund mit dem Ärmel ab.>\n\nArgh... Aber ich glaube, ich könnte eine Pause vertragen. Hier, nehmt diese Leuchtpistole, um damit Artillerieschläge auf den Strand anzufordern. Lasst die Hölle auf diese wertlosen, ziegenfüßigen Mistkerle herabregnen. Ich treffe Euch dann in der Basis wieder, wenn die Mission erledigt ist.", sourceObjective = "Tötet 14 Dämonen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45035] = { id = 45035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Schlacht", description = "Diese Dämonen kennen keine Ehre! Anstatt in einer glorreichen, offenen Schlacht gegen uns anzutreten, verschanzen sie sich hinter ihren Barrikaden und Belagerungswaffen.\n\nDie Valarjar sind angetreten, eine ruhmreiche Schlacht zu schlagen, und lassen sich von diesen feigen Taktiken nicht aufhalten!\n\nZerstört die Kanonen und Barrikaden, damit die Valarjar beweisen können, was wahrer Kampfgeist bedeutet! Wenn sich der Staub auf dem Schlachtfeld gelegt hat, werden nur die Leichen der Dämonen zurückbleiben... und die Valarjar einen weiteren Sieg feiern!" }
quests[45036] = { id = 45036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asgrim der Schreckenstöter", description = "Der Geist von einem unserer ehrenwertesten Krieger ist aus den Hallen der Tapferkeit verschwunden.\n\nAsgrim der Schreckenstöter war ein großer Kriegsfürst und König. Jahrhundertelang hat sich sein Geist an seinem rechtmäßigen Platz in den Hallen der Tapferkeit aufgehalten... bis vor Kurzem.\n\nVor unzähligen Jahren hat die Kriegsmeute des Schreckenstöters seine Knochen nicht weit von hier zur letzten Ruhe gebettet. Dort werden wir unsere Antworten finden.\n\nLasst Odyns Horn über seinem Grabhügel erschallen, um seinen Geist heraufzubeschwören.", sourceObjective = "Lasst Odyns Horn über dem Grabhügel von Asgrim dem Schreckenstöter erschallen, um seinen Geist heraufzubeschwören.", sourceObjectiveStatus = "unverified-source-field" }
quests[45037] = { id = 45037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Medaillon von Eldre'Thalas", description = "<Als Ihr das Medaillon vorsichtig öffnet, entdeckt Ihr ein vollständig aus wertvollen Edelsteinen gefertigtes Porträt von Königin Azshara.>\n\n<Es existieren nicht viele solcher wertvollen Schmuckstücke der Hochgeborenen. Und es in den Händen der Legion zu finden, ist äußerst besorgniserregend.>\n\n<Ihr seid Euch sicher, dass die Kirin Tor in Dalaran Euch mehr darüber erzählen können.>", sourceObjective = "Findet jemanden, der Euch mehr über das Medaillon von Eldre'Thalas erzählen kann. Ihr vermutet, dass Ihr mit Eurer Suche am besten bei den Kirin Tor in Dalaran beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45043] = { id = 45043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das leuchtende Blutdistelblatt", description = "<Man findet Blutdisteln ausgesprochen selten außerhalb der Blutelfenlande, ganz zu schweigen von einem so frischen Blatt wie diesem.>\n\n<Vielleicht hat die Legion es nur einem gefallenen Kämpfer abgenommen, aber diese Erklärung erscheint viel zu einfach.>\n\n<Ihr nehmt an, dass die Kirin Tor in Dalaran sicherlich daran interessiert wären.>", sourceObjective = "Findet jemanden, der an dem leuchtenden Blutdistelblatt interessiert ist. Ihr vermutet, dass Ihr am besten bei den Kirin Tor in Dalaran mit Eurer Suche beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45044] = { id = 45044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einst eine Waffe", description = "Der Speer, den Ihr gefunden habt, trägt offensichtlich alle Merkmale des Trollhandwerks, die Ihr bei anderen Schmiedeerzeugnissen gesehen habt.\n\nVielleicht kennt sich jemand in einem der Lager hier im Krater von Un'Goro damit besser aus.", sourceObjective = "Bringt den völlig zerstörten Dunkelspeer zu Ko'Zan auf dem Mooshügel im Krater von Un'Goro.\n\nBereitgestellter Gegenstand:", completion = "Ey Mann, was hast'n da in der Hand?\n\nDas is' doch nich' wirklich der Dunkelspeer, oder?! Ihr habt ihn gefunden?!", sourceObjectiveStatus = "unverified-source-field" }
quests[45045] = { id = 45045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Phiole mit uraltem Mana", description = "<Bei näherer Betrachtung scheint diese Phiole mit Mondbrunnenwasser gefüllt zu sein, das für seine starken arkanen Eigenschaften wohlbekannt ist.>\n\n<Interessanterweise scheint sie nicht von ihrem letzten Besitzer besudelt worden zu sein. Das sollte eigentlich tröstlich sein, aber es weckt nur Argwohn bezüglich ihres Ursprungsorts.>\n\n<Jemand bei den Kirin Tor in Dalaran wäre sicherlich daran interessiert.>", sourceObjective = "Findet jemanden, der an der Phiole mit uraltem Mana interessiert ist. Ihr vermutet, dass Ihr am besten bei den Kirin Tor in Dalaran mit Eurer Suche beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45046] = { id = 45046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Wind" }
quests[45047] = { id = 45047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Wind" }
quests[45048] = { id = 45048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Wind" }
quests[45049] = { id = 45049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Wind" }
quests[45050] = { id = 45050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrationspläne", description = "Obwohl der Text schwer zu verstehen und mit dämonischen Runen übersät ist, scheint es sich um Pläne zu handeln, Dalaran zu infiltrieren. Der Rat der Sechs wird dies sicherlich sehen wollen.", sourceObjective = "Bringt die Pläne zum Rat der Sechs in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[45051] = { id = 45051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was man zerlegen kann, kann man auch zusammenbauen!", description = "Und ich dachte schon, ich würde das Ding nie wieder seh'n!\n\nObwohl... sieht nich' mehr so aus wie früher. Oh Mann, ich krieg mächtig Ärger, wenn mich damit jemand erwischt.\n\nDenkt Ihr, dass Ihr mir helfen könnt, ihn zu reparieren? Ich hab allerdings keine Pläne dafür, denn in der ersten Nacht hier, kamen die Kreaturen der Wildnis und haben mir alles gestohlen.\n\nWas sagt Ihr, könnt Ihr einem Bruda aushelfen?\n\nIch denke, wenn Ihr herausfinden könnt, woraus der Speer besteht, könnt Ihr ihn auch reparieren. Und ich schreibe auf, wie man es macht.", sourceObjective = "Zerlegt den zerbrochenen Dunkelspeer.", completion = "Das sind ein paar echt krasse Materialien, aus denen das Teil besteht. Kein Wunda, dass der Chef es unbedingt hab'n will.", sourceObjectiveStatus = "unverified-source-field" }
quests[45052] = { id = 45052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgelaugter Netherkristall", description = "Der Kristall sieht wie etwas aus, das bei Ritualen mit dunkler Magie verwendet wird. Angesichts der Tatsache, dass seine Energie aufgebraucht ist, muss sein Besitzer bei der Durchführung seines Rituals, welches es auch gewesen sein mag, erfolgreich gewesen sein.\n\nDie Magier der Kirin Tor wären wahrscheinlich daran interessiert, dies näher zu untersuchen.", sourceObjective = "Bringt den Kristall zum Rat der Sechs in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[45053] = { id = 45053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instruktionen eines Diebes", description = "In der hastig hingekritzelten Botschaft steht:\n\n\"Ich benötige die fokussierende Iris für einen meinen Zauber. Zeigt, dass Ihr wirklich einer meiner besten Lehrlingse seid und bringt sie mir.\n\nOh, und achtet darauf, diese Notiz nicht irgendwo herumliegen zu lassen, damit nicht noch irgendein Abenteurer sie findet!\"\n\nWenn jemand darauf aus ist, die fokussierende Iris zu stehlen, dann möchten die Kirin Tor das bestimmt wissen.", sourceObjective = "Bringt die Instruktionen zum Rat der Sechs in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[45054] = { id = 45054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Uralte\" elfische Kriegsbefehle", description = "Diese Befehle sehen offiziell aus und tragen Rabenkrones Siegel, aber sie sind viel zu neu. Außerdem schimmert da ein Hauch von Teufelsmagie an ihren Rändern.\n\nDer Rat der Sechs hätte bestimmt Interesse, sich das anzusehen.", sourceObjective = "Bringt die gefälschten Befehle zum Rat der Sechs in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[45055] = { id = 45055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederholen ist nicht gestohlen", description = "Ich bin hier jetzt schon 'ne Weile in diesem Lager und ich weiß genau, dass man die Materialien alle hier in Un'Goro find'n kann.\n\nWird Zeit, es den Kreaturen hier heimzuzahl'n. Holt zurück, was sie mir geklaut haben! Das könnt Ihr doch für mich mach'n, <Bruder/Schwester>, oder?\n\nIch werd' hier einfach darauf warten, dass Ihr mit dem ganzen Kram zurückkommt.", sourceObjective = "Tötet die Kreaturen im Krater von Un'Goro und sammelt 5 gestohlene verzauberte Thoriumbarren, 5 größtenteils mächtiges Mojo, 2 versteinerte Dimetrodonschuppen und 2 gebleichte Stegodonstacheln. Bringt die gesammelten Materialien zu Ko'Zan.", progress = "Die miesen Maden kriegen, was sie verdienen!", completion = "Oh Mann, ich hätt' gern den Ausdruck in ihren Gesichtern geseh'n, während Ihr auf sie eingeschlagen habt.\n\nJetzt wo wir alle Materialien beisammen haben, brauchen wir sie nur noch zusammensetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45056] = { id = 45056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noressa", description = "Sie ist immer noch da drinnen, {name}. Noressa, meine Frau.\n\nSie ist auf der Promenade, während wir hier draußen warten und uns auf den Angriff vorbereiten. Wer weiß, was ihr zugestoßen ist?\n\nIch befürchte das Schlimmste. Bitte sagt ihr, dass es hier draußen noch Hoffnung gibt.\n\nWir hatten ein kleines Häuschen südlich der Großen Promenade, bei den Wassergärten. In diesen chaotischen Tagen wird sie sich wahrscheinlich dort aufhalten.", sourceObjective = "Rettet Noressa.", progress = "Ihr müsst sie finden!", completion = "Ich kann Euch wohl nicht genug danken. Wir werden wieder vereint sein, und ich werde dafür sorgen, dass wir nie wieder getrennt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[45057] = { id = 45057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meinen Hals retten", description = "Ich hab' mir gedacht, da Ihr ja ein Schmied seid und so, da is' es vielleicht am besten, wenn Ihr den Speer restauriert. Ihr könnt diese Schmiede dafür verwenden.\n\nIch fang' damit an, aufzuschreib'n, was zu tun ist, und dann hab'n wir beides, den Speer und den Bauplan!", sourceObjective = "Verwendet die Schmiede neben Ko'Zan dazu, den Dunkelspeer wiederherzustellen.", completion = "Das is' es, Mann!\n\nIch glaub', bevor ich wieder auf die Inseln zurückkehr', mach' ich zur Sicherheit noch ein paar weitere Kopien von diesen Plänen.\n\nEuch mach' ich auch 'ne Kopie. Für den Fall, dass ich bei der Herstellung von noch einem Exemplar Hilfe brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[45058] = { id = 45058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit die Schuppenwächter!" }
quests[45059] = { id = 45059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelserfülltes Totemfragment", description = "Dies scheint das Fragment eines Relikts oder Totems vom Hochberg zu sein. Es glüht unheimlich vor Teufelsmacht. Dies muss sofort zum Rat der Sechs in Dalaran gebracht werden!", sourceObjective = "Bringt das Totemfragment zum Rat der Sechs in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[45060] = { id = 45060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschädigtes Insigne der Kirin Tor", description = "Ganz gleich, ob es verloren oder gestohlen wurde, es ist seltsam, dass ein Dämon ein Insigne der Kirin Tor in seinem Besitz hat.\n\nDer Rat der Sechs wäre zweifellos an diesem Fund interessiert.", sourceObjective = "Bringt das Insigne zum Rat der Sechs in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[45061] = { id = 45061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schriftrollen der Faldrottin", description = "Obwohl es schon an sich ungewöhnlich wirkt, wenn ein Dämon eine Schriftrolle der Vrykul bei sich hat, ist deren Inhalt noch viel interessanter.\n\nEr scheint sich auf eine Vrykulprophezeiung zu beziehen, die von jemandem erzählt, der die Wellenskorn im Kampf gegen die Brennende Legion vereinen soll. Der Rat der Sechs muss sogleich von diesen Informationen erfahren.", sourceObjective = "Bringt die Schriftrollen zum Rat der Sechs in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[45062] = { id = 45062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter, immer weiter...", description = "Eure Entdeckungen sind alles andere als enttäuschend, {name}.\n\nBegebt Euch zur Seelenmaschine und nutzt Eure neu beschafften Waffen, um die Machtquelle zu zerlegen.", sourceObjective = "Benutzt die Verdorrten, um die Machtquelle in der Seelenmaschine der Teufelsseelenbastion zu zerlegen.", completion = "Oculeth wird über Eure Funde hocherfreut sein. Wie Ihr wisst, arbeitet er eifrig an einem neuen Gerät für die Verdorrten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45063] = { id = 45063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsseelenexperimente", description = "Andaris' Kontrolle über die Verdorrten stellt eine echte Bedrohung dar. Wenn wir den Widerstand der Verdorrten gegen diese Effekte stärken wollen, müssen wir es in einer Umgebung tun, die ebenjener Magie entsprungen ist.\n\nBegebt Euch sofort zur Teufelsseelenbastion. Wenn Ihr dort ankommt, schicke ich Verdorrte, die Euch unterstützen sollen. Es ist äußerst wichtig, dass Ihr nicht aufgebt, bevor Ihr sicher seid, dass die Experimente die passenden Ergebnisse liefern.", sourceObjective = "Erprobt den Widerstand der Verdorrten gegen Teufelsmagie in der Teufelsseelenbastion.", completion = "Die Verdorrten scheinen sich gut anzupassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45064] = { id = 45064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluss mit den Teufelsgeborenen", description = "Die Teufelsgeborenen weiten ihre Kontrolle über die Stadtgrenzen hinaus aus. Uns interessiert insbesondere ein Lager im Osten, im Purpurdickicht. Der Anführer dieses Lagers, Valthis Ama'ran, ist Andaris direkt unterstellt.\n\nEs ist an der Zeit, die Ausbildung unserer Verdorrten und Oculeths Gerät auf die Probe zu stellen. Wir dürfen nicht zulassen, dass sie weiter vorrücken, {name}.\n\nBegebt Euch zum Lager und benutzt die Kugel, um der Bestie den Kopf abzutrennen. Möge unser Vorstoß beginnen.", sourceObjective = "Tötet 8 Teufelsgeborene und ihren Anführer, Valthis Ama'ran, am Außenposten der Teufelsgeborenen im Purpurdickicht.", completion = "Unsere Bemühungen waren recht erfolgreich. Ich glaube, wir sind fast bereit, uns zur Wehr zu setzen.", sourceObjectiveStatus = "unverified-source-field" }
